fn legacy_scheme_color(value: &Value) -> Result<u8, String> {
    let index = any_whole_number(value)
        .ok_or_else(|| "SchemeColor takes a color scheme index".to_string())?;
    if !(0..=80).contains(&index) {
        return Err(host_error(5, "SchemeColor must be between 0 and 80"));
    }
    Ok(index as u8)
}

fn scheme_color_for_style(theme: Option<usize>, legacy: Option<u8>, color: i64, brightness: f64) -> i64 {
    scheme_color_for_style_in_palette(theme, legacy, color, brightness, &COLOUR_PALETTE)
}

#[derive(Clone, Copy)]
struct WindowsHls {
    hue: i64,
    luminance: i64,
    saturation: i64,
}

fn windows_hls_from_rgb(red: i64, green: i64, blue: i64) -> WindowsHls {
    let maximum = red.max(green).max(blue);
    let minimum = red.min(green).min(blue);
    let luminance = ((maximum + minimum) * 240 + 255) / 510;

    if maximum == minimum {
        return WindowsHls { hue: 160, luminance, saturation: 0 };
    }

    let delta = maximum - minimum;
    let saturation = if luminance <= 120 {
        ((maximum + minimum) / 2 + delta * 240) / (maximum + minimum)
    } else {
        ((510 - maximum - minimum) / 2 + delta * 240) / (510 - maximum - minimum)
    };
    let normalize = |channel| (delta / 2 + maximum * 40 - channel * 40) / delta;
    let red_normalized = normalize(red);
    let green_normalized = normalize(green);
    let blue_normalized = normalize(blue);
    let mut hue = if red == maximum {
        blue_normalized - green_normalized
    } else if green == maximum {
        80 + red_normalized - blue_normalized
    } else {
        160 + green_normalized - red_normalized
    };
    if hue < 0 {
        hue += 240;
    } else if hue > 240 {
        hue -= 240;
    }

    WindowsHls { hue, luminance, saturation }
}

fn nearest_direct_rgb_scheme_color(color: i64, palette: &[i64; 56]) -> i64 {
    let rgb = [color & 0xff, (color >> 8) & 0xff, (color >> 16) & 0xff];
    let chroma = rgb.iter().max().unwrap() - rgb.iter().min().unwrap();

    // Excel 16 COM samples use the workbook's current Colors palette for
    // unmatched RGB values too. Near-neutral inputs use palette entries with
    // channel spread <=10 when any exist; otherwise they fall through to
    // weighted Windows HLS distance, like chromatic inputs. Some
    // close-boundary results still differ, including RGB(179,119,19), where
    // Excel returns 52 while this metric has a unique minimum at 60. Exact
    // score ties use first palette order as a deterministic fallback.
    let has_neutral_entry = palette.iter().any(|held| {
        let channels = [held & 0xff, (held >> 8) & 0xff, (held >> 16) & 0xff];
        channels.iter().max().unwrap() - channels.iter().min().unwrap() <= 10
    });
    if chroma <= 10 && has_neutral_entry {
        let mean_times_three = rgb.iter().sum::<i64>();
        let mut nearest = 8;
        let mut best = i64::MAX;
        for (offset, held) in palette.iter().enumerate() {
            let channels = [held & 0xff, (held >> 8) & 0xff, (held >> 16) & 0xff];
            if channels.iter().max().unwrap() - channels.iter().min().unwrap() <= 10 {
                let gray_times_three = channels.iter().sum::<i64>();
                let score = (mean_times_three - gray_times_three).abs();
                if score < best {
                    nearest = offset as i64 + 8;
                    best = score;
                }
            }
        }
        return nearest;
    }

    let input = windows_hls_from_rgb(rgb[0], rgb[1], rgb[2]);
    let mut nearest = 8;
    let mut best = i64::MAX;
    for (offset, held) in palette.iter().enumerate() {
        let candidate = windows_hls_from_rgb(held & 0xff, (held >> 8) & 0xff, (held >> 16) & 0xff);
        let hue_delta = input.hue - candidate.hue;
        let luminance_delta = input.luminance - candidate.luminance;
        let saturation_delta = input.saturation - candidate.saturation;
        let score = 6 * hue_delta * hue_delta
            + 3 * luminance_delta * luminance_delta
            + saturation_delta * saturation_delta;
        if score < best {
            nearest = offset as i64 + 8;
            best = score;
        }
    }
    nearest
}

fn scheme_color_for_style_in_palette(
    _theme: Option<usize>,
    legacy: Option<u8>,
    color: i64,
    _brightness: f64,
    palette: &[i64; 56],
) -> i64 {
    if let Some(index) = legacy {
        return i64::from(index);
    }
    // Theme and brightness have already been resolved into `color` by the
    // ColorFormat getter. Excel derives SchemeColor from that resolved RGB
    // against the workbook palette; a default-theme lookup table gives wrong
    // answers whenever the workbook theme changes.
    // Excel 16 COM: direct RGB first searches Workbook.Colors(1..56), in
    // palette order. An exact hit returns the legacy scheme slot at that
    // position (Workbook.Colors index + 7), even when that moves a canonical
    // color such as red or white to a different slot. Duplicate colors use
    // the first matching palette slot; an unmatched color is quantized against
    // this same current palette.
    if let Some(offset) = palette.iter().position(|held| *held == color) {
        return offset as i64 + 8;
    }
    nearest_direct_rgb_scheme_color(color, palette)
}

/// A tint as given, checked and then quantised the way Excel keeps it: a
/// sixteen-bit fraction cut towards zero, so that 0.8 reads back
/// 0.799981688894314 and 0.4 reads back 0.399975585192419.
fn tint_asked(value: &Value) -> Result<f64, String> {
    let asked = any_number(value).ok_or_else(|| "TintAndShade takes a number".to_string())?;
    if !asked.is_finite() || !(-1.0..=1.0).contains(&asked) {
        return Err(host_error(5, "TintAndShade runs from -1 to 1"));
    }
    Ok(asked)
}

fn brightness_asked(value: &Value) -> Result<f64, String> {
    let asked = any_number(value).ok_or_else(|| "Brightness takes a number".to_string())?;
    if !asked.is_finite() || !(-1.0..=1.0).contains(&asked) {
        return Err(host_error(5, "Brightness runs from -1 to 1"));
    }
    Ok(asked)
}

fn quantised_tint(tint: f64) -> f64 {
    (tint * 32_767.0).trunc() / 32_767.0
}

/// Office ColorFormat.Brightness changes HSL lightness and writes the result
/// as DrawingML lumMod/lumOff. Keep this separate from the cell TintAndShade
/// routine, whose Win32 integer rounding differs by a few RGB units.
fn color_format_brightness(colour: i64, brightness: f64) -> i64 {
    if brightness == 0.0 {
        return colour;
    }
    let brightness = brightness as f32;
    let mut channels = [
        (colour & 0xff) as f32 / 255.0,
        ((colour >> 8) & 0xff) as f32 / 255.0,
        ((colour >> 16) & 0xff) as f32 / 255.0,
    ];
    let high = channels[0].max(channels[1]).max(channels[2]);
    let low = channels[0].min(channels[1]).min(channels[2]);
    let light = (high + low) / 2.0;
    let span = high - low;
    let wanted = if brightness > 0.0 {
        light + (1.0 - light) * brightness
    } else {
        light * (1.0 + brightness)
    };
    if span <= f32::EPSILON {
        channels = [wanted; 3];
    } else {
        let saturation = span / (1.0 - (2.0 * light - 1.0).abs()).max(f32::EPSILON);
        let reach = (1.0 - (2.0 * wanted - 1.0).abs()) * saturation.min(1.0);
        let scale = reach / span;
        for channel in &mut channels {
            *channel = (wanted + (*channel - light) * scale).clamp(0.0, 1.0);
        }
    }
    channels
        .iter()
        .enumerate()
        .map(|(index, channel)| ((channel * 255.0).round_ties_even() as i64) << (index * 8))
        .sum()
}

/// A colour with a tint on it, as Excel works it out.
///
/// Excel goes through hue, lightness and saturation in the classic Win32
/// way -- integer arithmetic on a 0..240 scale -- and moves the lightness:
/// towards 240 by the tint's share for a positive tint, towards 0 for a
/// negative one, the result truncated. The tint applied is the one given,
/// not the sixteen-bit one read back. Matched to 34 measured points over an
/// accent, black and a second accent, including the ones a floating-point
/// HLS gets wrong by one or two.
fn tinted(colour: i64, tint: f64) -> i64 {
    const HLSMAX: i64 = 240;
    const RGBMAX: i64 = 255;
    // No tint, no round trip: the conversion is lossy, and Excel hands the
    // theme colour back exactly.
    if tint == 0.0 {
        return colour;
    }
    let (r, g, b) = (colour & 0xff, (colour >> 8) & 0xff, (colour >> 16) & 0xff);
    let cmax = r.max(g).max(b);
    let cmin = r.min(g).min(b);
    let lightness = ((cmax + cmin) * HLSMAX + RGBMAX) / (2 * RGBMAX);
    let (hue, saturation) = if cmax == cmin {
        (0, 0)
    } else {
        let saturation = if lightness <= HLSMAX / 2 {
            ((cmax - cmin) * HLSMAX + (cmax + cmin) / 2) / (cmax + cmin)
        } else {
            ((cmax - cmin) * HLSMAX + (2 * RGBMAX - cmax - cmin) / 2) / (2 * RGBMAX - cmax - cmin)
        };
        let delta = |channel: i64| ((cmax - channel) * (HLSMAX / 6) + (cmax - cmin) / 2) / (cmax - cmin);
        let (red, green, blue) = (delta(r), delta(g), delta(b));
        let mut hue = if r == cmax {
            blue - green
        } else if g == cmax {
            HLSMAX / 3 + red - blue
        } else {
            2 * HLSMAX / 3 + green - red
        };
        if hue < 0 {
            hue += HLSMAX;
        }
        if hue > HLSMAX {
            hue -= HLSMAX;
        }
        (hue, saturation)
    };
    let moved = if tint < 0.0 {
        lightness as f64 * (1.0 + tint)
    } else {
        lightness as f64 * (1.0 - tint) + HLSMAX as f64 * tint
    };
    let lightness = (moved.floor() as i64).clamp(0, HLSMAX);
    if saturation == 0 {
        let grey = ((lightness * RGBMAX + HLSMAX / 2) / HLSMAX).clamp(0, RGBMAX);
        return grey | (grey << 8) | (grey << 16);
    }
    let magic2 = if lightness <= HLSMAX / 2 {
        (lightness * (HLSMAX + saturation) + HLSMAX / 2) / HLSMAX
    } else {
        lightness + saturation - (lightness * saturation + HLSMAX / 2) / HLSMAX
    };
    let magic1 = 2 * lightness - magic2;
    let hue_to_rgb = |mut hue: i64| -> i64 {
        if hue < 0 {
            hue += HLSMAX;
        }
        if hue > HLSMAX {
            hue -= HLSMAX;
        }
        if hue < HLSMAX / 6 {
            magic1 + ((magic2 - magic1) * hue + HLSMAX / 12) / (HLSMAX / 6)
        } else if hue < HLSMAX / 2 {
            magic2
        } else if hue < 2 * HLSMAX / 3 {
            magic1 + ((magic2 - magic1) * (2 * HLSMAX / 3 - hue) + HLSMAX / 12) / (HLSMAX / 6)
        } else {
            magic1
        }
    };
    let channel = |hue: i64| ((hue_to_rgb(hue) * RGBMAX + HLSMAX / 2) / HLSMAX).clamp(0, RGBMAX);
    let (red, green, blue) = (channel(hue + HLSMAX / 3), channel(hue), channel(hue - HLSMAX / 3));
    red | (green << 8) | (blue << 16)
}

/// Which part of a table an object speaks for.
#[derive(Debug, Clone, Copy)]
enum TablePart {
    Whole,
    Rows,
    Row(u32),
    Columns,
    Column(u32),
}

/// Which painted part of a cell a theme colour was given to.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Paint {
    Font,
    Interior,
    Edge(BorderSelection),
}

/// What `Worksheet.Protect` was asked for.
///
/// Measured against Excel, the flags divide the sheet three ways. `Contents`
/// covers the cells: with it, a LOCKED cell refuses a write, every cell
/// refuses a format, the columns refuse a width, the rows a height, the sheet
/// an insert, a delete, a sort and a merge -- each of the `Allow` flags
/// letting one of those through again -- and `Contents:=False` lets all of
/// them through. `UserInterfaceOnly` lifts all of that for macros and leaves
/// it for the person. `DrawingObjects` covers the notes: a protected sheet
/// refuses `AddComment` even with `UserInterfaceOnly`, even on an unlocked
/// cell, and even with `Contents:=False`, and only `DrawingObjects:=False`
/// lets one be added.
#[derive(Debug, Clone)]
struct Protection {
    password: String,
    contents: bool,
    drawing_objects: bool,
    user_interface_only: bool,
    allow_formatting_cells: bool,
    allow_formatting_columns: bool,
    allow_formatting_rows: bool,
    allow_inserting_columns: bool,
    allow_inserting_rows: bool,
    allow_deleting_columns: bool,
    allow_deleting_rows: bool,
    allow_sorting: bool,
    allow_inserting_hyperlinks: bool,
    allow_filtering: bool,
    allow_using_pivot_tables: bool,
}

impl Protection {
    /// Read off `Protect`'s arguments in their declared order: Password,
    /// DrawingObjects, Contents, Scenarios, UserInterfaceOnly, then the
    /// Allow flags -- FormattingCells, FormattingColumns, FormattingRows,
    /// InsertingColumns, InsertingRows, InsertingHyperlinks, DeletingColumns,
    /// DeletingRows, Sorting, Filtering, UsingPivotTables.
    fn asked(args: &[Value]) -> Result<Self, String> {
        let flag = |index: usize, default: bool| -> Result<bool, String> {
            match args.get(index) {
                None | Some(Value::Missing) => Ok(default),
                Some(value) => Ok(style_face_boolean(value, "Worksheet.Protect")?.unwrap_or(default)),
            }
        };
        Ok(Self {
            password: match args.first() {
                None | Some(Value::Missing) => String::new(),
                Some(value) => shown_text(value, None),
            },
            drawing_objects: flag(1, true)?,
            contents: flag(2, true)?,
            user_interface_only: flag(4, false)?,
            allow_formatting_cells: flag(5, false)?,
            allow_formatting_columns: flag(6, false)?,
            allow_formatting_rows: flag(7, false)?,
            allow_inserting_columns: flag(8, false)?,
            allow_inserting_rows: flag(9, false)?,
            allow_deleting_columns: flag(11, false)?,
            allow_deleting_rows: flag(12, false)?,
            allow_sorting: flag(13, false)?,
            allow_inserting_hyperlinks: flag(10, false)?,
            allow_filtering: flag(14, false)?,
            allow_using_pivot_tables: flag(15, false)?,
        })
    }
}

/// How `Range.TextToColumns` last split a column.
///
/// Excel keeps these from one call to the next: measured, a call naming no
/// delimiter at all splits on whatever the call before it named -- after
/// `Comma:=True, Tab:=False`, a bare `TextToColumns` splits `k,l` and leaves
/// a tab alone. A fresh Excel starts on Tab.
#[derive(Debug, Clone)]
struct SplitSettings {
    delimited: bool,
    consecutive: bool,
    /// The character that fences a field, or None for `xlTextQualifierNone`.
    qualifier: Option<char>,
    tab: bool,
    semicolon: bool,
    comma: bool,
    space: bool,
    other: Option<char>,
    trailing_minus: bool,
}

impl Default for SplitSettings {
    fn default() -> Self {
        Self {
            delimited: true,
            consecutive: false,
            qualifier: Some('"'),
            tab: true,
            semicolon: false,
            comma: false,
            space: false,
            other: None,
            trailing_minus: false,
        }
    }
}

/// What `FieldInfo` says about one field: where it starts (fixed width) or
/// which it is (delimited), and how to read it.
#[derive(Debug, Clone, Copy)]
struct FieldRule {
    at: usize,
    /// 1 General, 2 Text, 3-8 a date order, 9 skip the field.
    kind: i64,
}


/// One of the cell styles a new workbook carries.
///
/// What a style includes is what applying it sets; what it leaves out it
/// leaves alone. Measured on a Japanese Office: `Percent` includes only the
/// number, so a bold cell given it stays bold; `Normal` includes everything
/// and puts a cell back to bare; the themed styles include font and fill.
struct BuiltInStyle {
    /// The name `Range.Style = "..."` answers to. Six styles keep English
    /// names on a Japanese Office and the rest answer only to Japanese ones:
    /// `Range("A1").Style = "Good"` there is error 450.
    name: &'static str,
    local: &'static str,
    number: Option<&'static str>,
    font: Option<StyleFont>,
    /// Some(None) includes the fill and clears it; Some(Some(colour)) fills.
    fill: Option<Option<i64>>,
    /// Left, top, bottom, right, each a kind and a colour.
    borders: Option<[Option<(&'static str, i64)>; 4]>,
    alignment: bool,
    protection: bool,
    /// Where the font's colour is the theme's: its number.
    font_theme: Option<usize>,
    /// Where the fill is the theme's: its number and the tint.
    fill_theme: Option<(usize, f64)>,
}

struct StyleFont {
    bold: bool,
    italic: bool,
    underline: bool,
    size: f32,
    name: Option<&'static str>,
    /// A packed BGR colour; None is the automatic black.
    color: Option<i64>,
}

const NO_FONT_CHANGE: Option<StyleFont> = None;

const fn themed_font(color: Option<i64>) -> Option<StyleFont> {
    Some(StyleFont {
        bold: false,
        italic: false,
        underline: false,
        size: 11.0,
        name: None,
        color,
    })
}

const fn bold_font(color: Option<i64>, size: f32) -> Option<StyleFont> {
    Some(StyleFont {
        bold: true,
        italic: false,
        underline: false,
        size,
        name: None,
        color,
    })
}

const fn tint(
    name: &'static str,
    local: &'static str,
    fill: i64,
    accent: usize,
    shade: f64,
) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font: themed_font(None),
        fill: Some(Some(fill)),
        borders: None,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: Some((accent, shade)),
    }
}

const fn accent(name: &'static str, local: &'static str, fill: i64, accent: usize) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font: themed_font(Some(16_777_215)),
        fill: Some(Some(fill)),
        borders: None,
        alignment: false,
        protection: false,
        font_theme: Some(1),
        fill_theme: Some((accent, 0.0)),
    }
}

const fn numbered(name: &'static str, local: &'static str, format: &'static str) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: Some(format),
        font: NO_FONT_CHANGE,
        fill: None,
        borders: None,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: None,
    }
}

/// A style whose colours are all given as numbers.
const fn plain(
    name: &'static str,
    local: &'static str,
    font: Option<StyleFont>,
    fill: Option<Option<i64>>,
    borders: Option<[Option<(&'static str, i64)>; 4]>,
) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font,
        fill,
        borders,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: None,
    }
}

