fn vba_has_its_own(name: &str) -> bool {
    const ABSENT: &[&str] = &[
        // each of these is a VBA function of its own
        "ABS", "CHAR", "CODE", "DATE", "DAY", "HOUR", "INT", "LEFT", "LEN", "LOWER", "MID",
        "MINUTE", "MOD", "MONTH", "NOT", "RIGHT", "SECOND", "SQRT", "TIME", "UPPER", "VALUE",
        "YEAR", "DATEVALUE", "TIMEVALUE",
        // and each of these is said another way in VBA: `&` for CONCATENATE,
        // `=` for EXACT, `IsEmpty` for ISBLANK, `Range.Rows.Count` for ROWS
        "COLUMNS", "CONCATENATE", "DATEDIF", "EXACT", "HYPERLINK", "ISBLANK", "ISREF", "ROWS",
        // and the A forms that count text and logicals are not members at
        // all: measured, `Application.AverageA(1, 2)` and `MaxA`, `MinA`,
        // `StDevA`, `StDevPA`, `VarA`, `VarPA` are each 438.
        "AVERAGEA", "MAXA", "MINA", "STDEVA", "STDEVPA", "VARA", "VARPA",
        // and ERROR.TYPE, which VBA asks of an error with CVErr's number:
        // measured, `WorksheetFunction.Error_Type` is 438.
        "ERROR.TYPE", "ERROR_TYPE",
        // and the newer functions the object model never took in: measured,
        // each of these is 438 from WorksheetFunction while Unique, Sort,
        // Sequence, Concat, XLookup and ArrayToText answer.
        "TAKE", "DROP", "TOCOL", "TOROW", "VSTACK", "HSTACK", "CHOOSECOLS", "CHOOSEROWS",
        "WRAPROWS", "WRAPCOLS", "EXPAND", "TEXTSPLIT", "TEXTBEFORE", "TEXTAFTER", "LAMBDA",
        "LET", "BYROW", "BYCOL", "MAP", "REDUCE", "SCAN", "MAKEARRAY", "ISOMITTED", "GROUPBY",
        "PIVOTBY", "PERCENTOF", "TRIMRANGE", "REGEXTEST", "REGEXEXTRACT", "REGEXREPLACE",
        "IMAGE", "IFS", "SWITCH", "SHEET", "SHEETS", "FORMULATEXT",
        // and, asked of every name the engine knows, these too: the ones VBA
        // says its own way (Atn, Cos, Exp, Sgn, Fix, Now, Rnd, IIf, True),
        // the byte forms, and the ones about references.
        "ADDRESS", "AREAS", "ATAN", "CELL", "COLUMN", "COS", "ECMA.CEILING", "ECMA_CEILING",
        "EXP", "FALSE", "IF", "INDIRECT", "INFO", "LEFTB", "LENB", "MIDB", "RIGHTB", "N", "NA",
        "NOW", "OFFSET", "RAND", "ROW", "SIGN", "SIN", "T", "TAN", "TODAY", "TRUE", "TRUNC",
        "TYPE", "YIELD",
        // DATEDIF's units, which the engine lists among its names.
        "D", "M", "Y", "MD", "YM", "YD",
    ];
    ABSENT
        .iter()
        .any(|absent| absent.eq_ignore_ascii_case(name))
}

/// One value, put the way the engine holds one.
fn engine_value(value: &Value) -> oxicells_calc::Value {
    use oxicells_calc::{ExcelError, Value as Sheet};
    match value {
        Value::Double(number) if !number.is_finite() => Sheet::Error(ExcelError::Num),
        value if any_number(value).is_some() => Sheet::Number(any_number(value).unwrap_or_default()),
        Value::String(text) => Sheet::Text(text.clone()),
        Value::Utf16(units) => Sheet::Utf16(units.clone()),
        Value::NullString => Sheet::Text(String::new()),
        Value::Boolean(state) => Sheet::Logical(*state),
        Value::Error(number) => Sheet::Error(match spreadsheet_error_text(*number) {
            "#NULL!" => ExcelError::Null,
            "#DIV/0!" => ExcelError::DivZero,
            "#REF!" => ExcelError::Ref,
            "#NAME?" => ExcelError::Name,
            "#NUM!" => ExcelError::Num,
            "#N/A" => ExcelError::NA,
            _ => ExcelError::Value,
        }),
        _ => Sheet::Blank,
    }
}

/// The error values a worksheet function answers with, measured on Excel
/// 16.0 through `Application`: a lookup that misses is 2042, an index past
/// the end of its table 2023, an average of nothing 2007, a median of nothing
/// or a ninth-largest of two numbers 2036. `WorksheetFunction` raises on every
/// one of them instead.
///
/// Not yet told apart: an argument of the wrong sort — `Sum("text")`, an
/// index of nought — which Excel answers 2015 through `Application` and this
/// build raises on both paths. A raise is loud, where a wrong number would
/// not be, so it waits.
const ERROR_DIV_ZERO: i64 = 2007;
const ERROR_REF: i64 = 2023;
const ERROR_NUM: i64 = 2036;
const ERROR_NA: i64 = 2042;

/// The error a written word names, where it names one.
///
/// Asked of Excel by writing each into a cell: the seven a sheet can work out
/// for itself and `#GETTING_DATA` are taken, in any case -- `"#n/a"` becomes
/// `#N/A` -- and with nothing around them, since `" #N/A"` and `"#N/A "` both
/// stay text. Nothing else beginning with a hash is taken: `"#NOPE!"` stays
/// text, and so does `"#SPILL!"`, though a sheet can work that one out itself.
fn written_error(written: &str) -> Option<&'static str> {
    match written.to_ascii_uppercase().as_str() {
        "#NULL!" => Some("#NULL!"),
        "#DIV/0!" => Some("#DIV/0!"),
        "#VALUE!" => Some("#VALUE!"),
        "#REF!" => Some("#REF!"),
        "#NAME?" => Some("#NAME?"),
        "#NUM!" => Some("#NUM!"),
        "#N/A" => Some("#N/A"),
        "#GETTING_DATA" => Some("#GETTING_DATA"),
        _ => None,
    }
}

fn spreadsheet_error_number(value: &str) -> i64 {
    match value.to_ascii_uppercase().as_str() {
        "#NULL!" => 2000,
        "#DIV/0!" => 2007,
        "#VALUE!" => 2015,
        "#REF!" => 2023,
        "#NAME?" => 2029,
        "#NUM!" => 2036,
        "#N/A" => 2042,
        "#GETTING_DATA" => 2043,
        "#SPILL!" => 2045,
        "#CONNECT!" => 2046,
        "#BLOCKED!" => 2047,
        "#UNKNOWN!" => 2048,
        "#FIELD!" => 2049,
        "#CALC!" => 2050,
        _ => 2015,
    }
}

/// The cell text for an error code, or `None` when the number names no error.
///
/// Separate from `spreadsheet_error_text` because that one answers #VALUE! for
/// anything it does not know, which is the right reading when a number is
/// already known to be an error and the wrong one when the question is whether
/// it IS an error at all.
fn spreadsheet_error_text_exact(value: i64) -> Option<&'static str> {
    match value {
        2000 => Some("#NULL!"),
        2007 => Some("#DIV/0!"),
        2015 => Some("#VALUE!"),
        2023 => Some("#REF!"),
        2029 => Some("#NAME?"),
        2036 => Some("#NUM!"),
        2042 => Some("#N/A"),
        2043 => Some("#GETTING_DATA"),
        2045 => Some("#SPILL!"),
        2046 => Some("#CONNECT!"),
        2047 => Some("#BLOCKED!"),
        2048 => Some("#UNKNOWN!"),
        2049 => Some("#FIELD!"),
        2050 => Some("#CALC!"),
        _ => None,
    }
}

fn spreadsheet_error_text(value: i64) -> &'static str {
    match value {
        2000 => "#NULL!",
        2007 => "#DIV/0!",
        2015 => "#VALUE!",
        2023 => "#REF!",
        2029 => "#NAME?",
        2036 => "#NUM!",
        2042 => "#N/A",
        2043 => "#GETTING_DATA",
        2045 => "#SPILL!",
        2046 => "#CONNECT!",
        2047 => "#BLOCKED!",
        2048 => "#UNKNOWN!",
        2049 => "#FIELD!",
        2050 => "#CALC!",
        _ => "#VALUE!",
    }
}

#[derive(Serialize)]
struct OutputArrayDimension {
    lower_bound: i64,
    length: usize,
}

#[derive(Serialize)]
struct RunResult {
    workbook: Workbook,
    result: OutputValue,
    debug_output: Vec<String>,
    messages: Vec<BrowserMessage>,
    /// What the macro left across the status bar, if it wrote one. Excel does
    /// not clear it when the macro ends — a macro that forgets to give the bar
    /// back leaves its last word showing — so the page is told the last thing
    /// written rather than nothing.
    status_bar: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    files: Vec<file_io::ProducedFile>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    deleted_files: Vec<String>,
}

#[derive(Serialize)]
struct RunFailure {
    message: String,
    kind: &'static str,
    line: Option<u32>,
}

/// The workbook and outputs at the point execution stopped, including failure.
#[derive(Serialize)]
struct RunOutcome {
    workbook: Workbook,
    result: OutputValue,
    debug_output: Vec<String>,
    messages: Vec<BrowserMessage>,
    status_bar: Option<String>,
    error: Option<RunFailure>,
    workbook_changed: bool,
    active_sheet: usize,
    application_state: VbaApplicationState,
    file_system_state: file_io::FileSystemState,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    files: Vec<file_io::ProducedFile>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    deleted_files: Vec<String>,
}

impl RunOutcome {
    fn into_result(self) -> RunResult {
        RunResult { workbook: self.workbook, result: self.result, debug_output: self.debug_output,
            messages: self.messages, status_bar: self.status_bar, files: self.files, deleted_files: self.deleted_files }
    }
}

