    #[test]
    fn project_macro_host_invocation_matches_native_excel() {
        let fixtures = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let cases: Vec<serde_json::Value> = serde_json::from_str(include_str!("../../../tests/fixtures/vba/macro_entry_points.json")).unwrap();
        for case in cases {
            let source = std::fs::read_to_string(fixtures.join(case["source"].as_str().unwrap())).unwrap();
            let (module, classes) = oxivba_core::parse_project(&source).unwrap();
            let documents: Vec<VbaDocumentModule> = serde_json::from_value(case["document_modules"].clone()).unwrap();
            let mut book = workbook();
            book.sheets[0].name = case["host_context"]["sheets"][0]["name"].as_str().unwrap().to_string();
            let mut host = WorkbookHost::new(&mut book, 0).unwrap();
            host.configure_documents(&documents).unwrap();
            host.file_name = Some(case["host_context"]["book_name"].as_str().unwrap().to_string());
            host.automation_code_page = Some(AnsiCodePage::Japanese);
            let bindings = host.document_objects.iter().map(|(name, object)| (name.clone(), object.clone())).collect();
            let mut references = builtin_compilation_references().clone();
            references.document_modules = documents.iter().map(|document| (document.name.clone(), document.base_type.clone())).collect();
            let mut runtime = Runtime::new(&module).with_classes(&classes).with_host(&mut host)
                .with_document_objects(bindings, std::sync::Arc::new(references)).unwrap();
            for call in 0..3 {
                let actual = runtime.invoke_host("Application", "Run", vec![Value::String(case["procedure"].as_str().unwrap().to_string())]).unwrap();
                assert_eq!(actual, Value::String(case["expected"].as_str().unwrap().to_string()), "{} call{call}", case["name"]);
            }
        }
    }

    #[test]
    fn project_entry_points_retain_owners_and_source_positions() {
        let fixtures = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let cases: Vec<serde_json::Value> = serde_json::from_str(include_str!("../../../tests/fixtures/vba/macro_entry_points.json")).unwrap();
        for case in cases {
            let source = std::fs::read_to_string(fixtures.join(case["source"].as_str().unwrap())).unwrap();
            let documents: Vec<VbaDocumentModule> = serde_json::from_value(case["document_modules"].clone()).unwrap();
            let summaries = spreadsheet_vba_project_procedures(&source, &documents).unwrap();
            let mut listed = serde_json::to_value(&summaries).unwrap();
            for (summary, listed) in summaries.iter().zip(listed.as_array_mut().unwrap()) {
                let text = source.lines().nth(summary.line as usize - 1).unwrap();
                assert!(text.to_ascii_lowercase().contains(&summary.name.rsplit('.').next().unwrap().to_ascii_lowercase()), "{} at {}: {text}", summary.name, summary.line);
                listed.as_object_mut().unwrap().remove("line");
            }
            assert_eq!(listed, case["expected_procedures"], "{}", case["name"]);
            assert!(spreadsheet_vba_procedures(&source).unwrap().iter().all(|summary| summary.module_kind == Some("standard")));
        }
    }

    fn assert_native_callbyname_cases(fixture: &str) {
        let fixtures = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let cases: Vec<serde_json::Value> = serde_json::from_str(fixture).unwrap();
        let mut failures = Vec::new();
        for case in &cases {
            let source = std::fs::read_to_string(fixtures.join(case["source"].as_str().unwrap())).unwrap();
            let mut book = workbook();
            book.sheets[0].name = case["host_context"]["sheets"][0]["name"].as_str().unwrap().to_string();
            let mut session = None;
            for call in 0..3 {
                let mut context = failure_context();
                context.host_ansi_code_page = Some(AnsiCodePage::Japanese);
                if case["execution_options"]["errorLanguage"] == "ja-JP" { context.environment.language = ErrorLanguage::Japanese; }
                context.file_name = Some(case["host_context"]["book_name"].as_str().unwrap().to_string());
                context.document_modules = Some(serde_json::from_value(case["document_modules"].clone()).unwrap());
                let outcome = execute_workbook_action_in_session(book, &source, Some(case["procedure"].as_str().unwrap()), vec![], 0, context, &mut session).unwrap();
                assert!(outcome.error.is_none(), "{}: {:?}", case["name"], outcome.error.as_ref().map(|e| &e.message));
                let actual = serde_json::to_value(&outcome.result).unwrap();
                let expected = case["expected"].as_str().unwrap();
                let actual = actual["value"].as_str().unwrap();
                if actual != expected {
                    for (want, got) in expected.lines().zip(actual.lines()) {
                        if want != got { failures.push(format!("{} call{call}: {want} <> {got}",case["name"])); }
                    }
                    if expected.lines().count() != actual.lines().count() { failures.push(format!("{}: output line count differs",case["name"])); }
                }
                book = outcome.workbook;
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

