    #[test]
    fn chart_properties_survive_native_file_import_and_fresh_session_save() {
        let fixtures=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/vba");
        let cases:serde_json::Value=serde_json::from_str(include_str!("../../../tests/fixtures/vba/chart_persistence.json")).unwrap();
        let mut failures=Vec::new();
        for case in cases.as_array().unwrap() {
            let original=std::fs::read(fixtures.join(case["package_fixture"].as_str().unwrap())).unwrap();
            let source=std::fs::read_to_string(fixtures.join(case["source"].as_str().unwrap())).unwrap();
            let documents:Vec<VbaDocumentModule>=serde_json::from_value(case["metadata_before"].clone()).unwrap();
            let mut refs=builtin_compilation_references().clone();
            refs.document_modules=documents.iter().map(|doc|(doc.name.clone(),doc.base_type.clone())).collect();
            assert!(compilation_outcome(&source,ErrorLanguage::Japanese,&refs).compiled,"{}",case["name"]);
            let mut book=oxicells_core::parse_xlsx(&original).unwrap();
            let mut session=None;
            let active=case["host_context"]["active_sheet"].as_u64().unwrap() as usize;
            for (stage,procedure) in [("initial",case["procedure"].as_str().unwrap()),("change",case["change_procedure"].as_str().unwrap()),("changed",case["procedure"].as_str().unwrap())] {
                let mut context=failure_context();context.document_modules=Some(documents.clone());
                let result=execute_workbook_action_in_session(book,&source,Some(procedure),vec![],active,context,&mut session).unwrap();
                if stage!="change" {
                    let expected=case["steps"].as_array().unwrap().iter().find(|step|step["stage"]==stage).unwrap();
                    let value=serde_json::to_value(&result.result).unwrap();
                    if result.error.is_some() || value!=serde_json::json!({"type":"string","value":expected["value"]}) {
                        failures.push(format!("{} {stage}: {value}; {:?}",case["name"],result.error.as_ref().map(|e|&e.message)));
                    }
                } else {assert!(result.error.is_none(),"{}: {:?}",case["name"],result.error.as_ref().map(|e|&e.message));}
                book=result.workbook;
            }
            let mut editor=oxicells_core::XlsxEditor::new(&original).unwrap();
            editor.apply_workbook(&book).unwrap();
            let saved=editor.save().unwrap();
            if let Ok(directory)=std::env::var("OXI_CHART_PERSISTENCE_OUTPUT") {
                let directory=std::path::PathBuf::from(directory);
                std::fs::create_dir_all(&directory).unwrap();
                std::fs::write(directory.join(format!("{}.xlsm",case["name"].as_str().unwrap())),&saved).unwrap();
            }

            let mut fresh=None;
            let mut context=failure_context();context.document_modules=Some(documents.clone());
            let result=execute_workbook_action_in_session(oxicells_core::parse_xlsx(&saved).unwrap(),&source,Some(case["procedure"].as_str().unwrap()),vec![],active,context,&mut fresh).unwrap();
            let value=serde_json::to_value(&result.result).unwrap();
            if result.error.is_some() || value!=serde_json::json!({"type":"string","value":case["steps"][2]["value"]}) {
                failures.push(format!("{} reopened: {value}; {:?}",case["name"],result.error.as_ref().map(|e|&e.message)));
            }
        }
        assert!(failures.is_empty(),"{}",failures.join("\n"));
    }

