            // knows the display filename. Its remembered cwd may have no
            // entries in a freshly replaced closed namespace yet.
            context.application_state=Some(VbaApplicationState {directory_state:Some(VbaDirectoryState {current_drive:"D".into(),directories:vec!["C:\\".into(),"D:\\ambient\\work".into()]}),..Default::default()});
            context.file_name=Some("input.xlsm".into());
            context.file_context=Some(file_io::FileContext {package_bytes:Some(package.clone()),..Default::default()});
            context.file_system_state=Some(serde_json::from_value(serde_json::json!({"folders":[],"files":[],"mountedFolders":[],"mountedFiles":[],"volumes":fixture["volumes"]})).unwrap());
            context.document_modules=Some(crate::vba_project::read_document_modules(&package).unwrap());
