    #[test]
    fn excel_localized_errors_with_workbook_host() {
        const HELP_FILE: &str = r"C:\Oxi\VBA\1041\VbLR6.chm";
        let module = parse_module(include_str!("../../../tests/fixtures/vba/localized_errors_ja.bas")).unwrap();
        assert_eq!(oxivba_core::analyse(&module).metrics.unparsed, 0);
        let mut failures = Vec::new();
        let mut compared = BTreeSet::new();
        for case in include_str!("../../../tests/fixtures/vba/localized_errors_ja.tsv").lines() {
            let (name, expected) = case.split_once('\t').unwrap();
            assert!(compared.insert(name));
            let mut workbook = workbook();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let environment = VbaExecutionOptions {
                error_language: Some("ja-JP".to_string()),
                host_ansi_code_page: None,
                worksheet_dbcs_language: None,
                vba_help_file: Some(HELP_FILE.to_string()),
                project_name: None,
                application_state: None,
                source_edits: None,
                document_modules: None,
                file_context: None,
                file_system_state: None,
            }.error_environment().unwrap();
            host.error_language = environment.language;
            let actual = Runtime::new(&module).with_host(&mut host)
                .with_error_environment(environment).call(name, vec![]);
            let expected = Value::String(expected.replace("{VBA_HELP}", HELP_FILE));
            if actual != Ok(expected.clone()) {
                failures.push(format!("{name}: expected {expected:?}, got {actual:?}"));
            }
        }
        let public: BTreeSet<_> = module.items.iter().filter_map(|item| match item {
            ModuleItem::Procedure(procedure) if procedure.visibility == Visibility::Public => Some(procedure.name.as_str()),
            _ => None,
        }).collect();
        assert_eq!(compared, public);
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

