    #[test]
    fn table_auto_filter_keeps_table_bounds_headers_totals_and_field_origin() {
        for target in ["t.Range", "Range(\"A1:B1\")", "Range(\"A1:A3\")", "Range(\"B1:B3\")", "Range(\"A2:B3\")", "Range(\"B2:B3\")", "Range(\"B2\")"] {
            let mut book = workbook();
            let module = parse_module(&format!(r#"Public Function Probe() As String
                Dim t As Object
                Range("A1").Value="X":Range("B1").Value="Y"
                Range("A2").Value=1:Range("B2").Value=2
                Range("A3").Value=3:Range("B3").Value=4
                Range("C4").Value="outside"
                Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B3"),,xlYes)
                {target}.AutoFilter 1,1
                Probe=Rows(2).Hidden & "|" & Rows(3).Hidden & "|" & Rows(4).Hidden & "|" & t.ShowAutoFilter
            End Function"#)).unwrap();
            let answer = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
            assert_eq!(answer, Value::String("False|True|False|True".into()), "{target}");
        }
        for totals in [false, true] {
            for headers in [false, true] {
                let mut book = workbook();
                let module = parse_module(&format!(r#"Public Function Probe() As String
                    Dim t As Object
                    Range("A1").Value="X":Range("B1").Value="Y"
                    Range("A2").Value=1:Range("B2").Value=2
                    Range("A3").Value=3:Range("B3").Value=4
                    Range("C4").Value="outside"
                    Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B3"),,xlYes)
                    t.ShowTotals={totals}
                    t.ShowHeaders={headers}
                    t.Range.AutoFilter 1,1
                    Probe=t.ShowHeaders & "|" & t.ShowTotals & "|" & t.ListRows.Count & "|" & Rows(3).Hidden & "|" & Rows(4).Hidden
                End Function"#)).unwrap();
                let answer = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
                assert_eq!(answer, Value::String(format!("True|{}|2|True|False", if totals { "True" } else { "False" })));
            }
        }
        for headers in [false, true] {
            let mut book = workbook();
            let module = parse_module(&format!(r#"Public Function Probe() As String
                Dim t As Object, out As String
                Range("A1").Value="X":Range("B1").Value="Y"
                Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B3"),,xlYes)
                t.ShowHeaders={headers}
                t.Range.AutoFilter
                out=t.ShowHeaders & "|" & t.ShowAutoFilter & "|"
                t.Range.AutoFilter
                Probe=out & t.ShowHeaders & "|" & t.ShowAutoFilter
            End Function"#)).unwrap();
            let answer = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
            assert_eq!(answer, Value::String(if headers { "True|False|True|True" } else { "True|True|True|False" }.into()));
        }
        for property in ["ShowAutoFilter", "ShowHeaders"] {
            let mut book = workbook();
            let module = parse_module(&format!(r#"Public Function Probe() As String
                Dim t As Object, out As String
                Range("A1").Value="X":Range("B1").Value="Y"
                Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B1"),,xlYes)
                t.ShowTotals=True
                t.Range.AutoFilter 1,1
                out=t.ListRows.Count & "|" & Rows(2).Hidden & "|" & Rows(3).Hidden & "|"
                t.{property}=False
                Probe=out & Rows(2).Hidden
            End Function"#)).unwrap();
            let answer = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
            assert_eq!(answer, Value::String("0|True|False|False".into()), "{property}");
        }
    }

    #[test]
    fn table_totals_settings_labels_and_utf16_custom_formulas_survive_save() {
        let original = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        for mode in [-4105, -4135] {
            let mut book = oxicells_core::parse_xlsx(original).unwrap();
            let setup = parse_module(&format!(r#"Public Function Setup() As String
                Dim t As Object
                Range("A1:H12").Clear
                Range("A1").Value="X":Range("B1").Value="Y"
                Range("A2").Value=1:Range("B2").Value=2
                Range("A3").Value=3:Range("B3").Value=4
                Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B3"),,xlYes)
                t.Name="T"
                Application.Calculation={mode}
                t.ShowTotals=True
                Setup=t.ListColumns(2).TotalsCalculation & "|" & Range("B4").Value2
            End Function"#)).unwrap();
            let answer = execute_with_host(&setup, "Setup", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
            assert_eq!(answer, Value::String("1|6".into()), "initial mode {mode}");
            let read = parse_module("Public Function Read() As String\nRead=ActiveSheet.ListObjects(1).ListColumns(2).TotalsCalculation & \"|\" & Range(\"A4\").Value2\nEnd Function").unwrap();
            for (action, calculation, value) in [
                ("Range(\"A4\").Value=\"grand\"\nt.ListColumns(2).TotalsCalculation=2", 2, CellValue::Number(3.0)),
                ("t.ShowTotals=False\nt.ShowTotals=True", 2, CellValue::Number(3.0)),
                ("Range(\"B4\").Value2=7", 0, CellValue::String("7".into())),
                ("Range(\"B4\").Value2=True", 0, CellValue::String("TRUE".into())),
                ("Range(\"B4\").Formula=\"=SUM(T[Y])&\"\"a\" & ChrW(&HD83D) & \"b\"\"\"", 9, CellValue::Utf16(vec![54,97,0xD83D,98])),
                ("t.Name=\"Renamed\"\nt.ListColumns(2).Name=\"Quantity\"", 9, CellValue::Utf16(vec![54,97,0xD83D,98])),
            ] {
                let module = parse_module(&format!("Public Sub Change()\nDim t As Object\nSet t=ActiveSheet.ListObjects(1)\nApplication.Calculation={mode}\n{action}\nEnd Sub")).unwrap();
                execute_with_host(&module, "Change", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
                for reopened in [false, true] {
                    if reopened {
                        let mut editor = oxicells_core::XlsxEditor::new(original).unwrap();
                        editor.apply_workbook(&book).unwrap();
                        book = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
                    }
                    let mut host = WorkbookHost::new(&mut book, 0).unwrap();
                    let answer = execute_with_host(&read, "Read", vec![], &mut host).unwrap();
                    assert_eq!(answer, Value::String(format!("{calculation}|grand")), "mode={mode} reopened={reopened} {action}");
                    let cell = host.cell_here(0, 4, 1).unwrap();
                    assert_eq!(serde_json::to_value(&cell.value).unwrap(), serde_json::to_value(&value).unwrap());
                    let totals = &host.workbook.sheets[0].tables[0].totals[1];
                    if calculation == 9 { assert_eq!(totals.formula.as_deref(), cell.formula_units().as_deref()); }
                }
            }
        }
    }

    #[test]
    fn table_auto_filter_is_saved_in_the_table_without_worksheet_filter_names() {
        let original = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut book = oxicells_core::parse_xlsx(original).unwrap();
        let module = parse_module(r#"Public Sub Setup()
            Range("A1:H12").Clear
            Range("A1").Value="X":Range("B1").Value="Y"
            Range("A2").Value=1:Range("A3").Value=3
            Range("C4").Value="outside"
            Dim t As Object
            Set t=ActiveSheet.ListObjects.Add(xlSrcRange,Range("A1:B3"),,xlYes)
            t.Range.AutoFilter 1,1
        End Sub"#).unwrap();
        execute_with_host(&module, "Setup", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
        for reopened in [false, true] {
            if reopened {
                let mut editor = oxicells_core::XlsxEditor::new(original).unwrap();
                editor.apply_workbook(&book).unwrap();
                book = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            }
            assert!(book.sheets[0].auto_filter.is_none());
            assert!(book.sheets[0].tables[0].has_filter_criteria());
            assert!(book.defined_names.iter().all(|(name, _)| !name.ends_with("!_FilterDatabase")));
            assert!(book.sheets[0].rows.iter().find(|row| row.index==3).unwrap().hidden);
            assert!(!book.sheets[0].rows.iter().find(|row| row.index==4).unwrap().hidden);
        }
        let hide = parse_module("Public Sub Hide()\nActiveSheet.ListObjects(1).ShowHeaders=False\nEnd Sub").unwrap();
        execute_with_host(&hide, "Hide", vec![], &mut WorkbookHost::new(&mut book, 0).unwrap()).unwrap();
        assert!(!book.sheets[0].tables[0].has_filter_criteria());
        assert!(!book.sheets[0].rows.iter().find(|row| row.index==3).unwrap().hidden);
    }

    #[test]
    fn table_style_and_filter_flags_match_excel_values_errors_and_saved_state() {
        let mut workbook = workbook();
        let module = parse_module(r#"Public Function Ask() As String
            Dim lo As Object, out As String
            Range("A1").Value = "X"
            Range("B1").Value = "Y"
            Set lo = ActiveSheet.ListObjects.Add(xlSrcRange, Range("A1:B3"), , xlYes)
            out = lo.ShowTableStyleFirstColumn & lo.ShowTableStyleLastColumn & lo.ShowTableStyleRowStripes & lo.ShowTableStyleColumnStripes & lo.ShowAutoFilter & lo.ShowAutoFilterDropDown & "|"
            ThisWorkbook.Saved = True
            lo.ShowTableStyleFirstColumn = "True"
            lo.ShowTableStyleLastColumn = "1"
            lo.ShowTableStyleRowStripes = "0"
            lo.ShowTableStyleColumnStripes = 0.4
            out = out & lo.ShowTableStyleFirstColumn & lo.ShowTableStyleLastColumn & lo.ShowTableStyleRowStripes & lo.ShowTableStyleColumnStripes & ThisWorkbook.Saved & "|"
            ThisWorkbook.Saved = True
            lo.ShowTableStyleColumnStripes = True
            out = out & ThisWorkbook.Saved & "|"
            ThisWorkbook.Saved = True
            lo.ShowAutoFilter = True
            lo.ShowAutoFilterDropDown = True
            out = out & ThisWorkbook.Saved & "|"
            lo.ShowAutoFilterDropDown = False
            out = out & lo.ShowAutoFilter & lo.ShowAutoFilterDropDown & ThisWorkbook.Saved & "|"
            ThisWorkbook.Saved = True
            lo.ShowAutoFilterDropDown = False
            out = out & ThisWorkbook.Saved & "|"
            lo.ShowAutoFilter = False
            out = out & lo.ShowAutoFilter & lo.ShowAutoFilterDropDown & "|"
            On Error Resume Next
            lo.ShowAutoFilterDropDown = True
            out = out & Err.Number & "|"
            Err.Clear
            lo.ShowTableStyleFirstColumn = Null
            out = out & Err.Number & "|"
            Err.Clear
            lo.ShowTableStyleRowStripes = ""
            out = out & Err.Number & "|"
            Err.Clear
            lo.ShowAutoFilter = True
            out = out & lo.ShowAutoFilterDropDown
            Ask = out
        End Function"#).unwrap();
        let actual = execute_with_host(&module, "Ask", vec![], &mut WorkbookHost::new(&mut workbook, 0).unwrap()).unwrap();
        assert_eq!(actual, Value::String("FalseFalseTrueFalseTrueTrue|TrueTrueFalseTrueFalse|False|True|TrueFalseFalse|True|FalseFalse|1004|13|13|True".into()));
        let table = &workbook.sheets[0].tables[0];
        assert!(table.emphasize_first_column && table.emphasize_last_column && table.banded_columns);
        assert!(!table.banded_rows);
        assert!(table.show_auto_filter);
        assert!(table.hidden_filter_buttons.is_empty());
    }

    /// Conditional formats are added, read, worked out and taken away as
    /// Excel does it.
    ///
    /// Measured against Excel: `Add` answers a FormatCondition whose Formula1
    /// is kept with its `=`; `Count` is the number of conditions reaching the
    /// range; a condition's font and fill are set on it, not on the cells,
    /// and `DisplayFormat` shows them where the condition holds -- text
    /// counts as above any number; two conditions layer in priority order,
    /// with `SetFirstPriority` reordering; `Between` without Formula2 is 449;
    /// deleting one cell's conditions cuts it out of the block; a copy takes
    /// the conditions along for itself; and `ClearFormats` takes them away.
    #[test]
    fn loaded_conditional_formats_are_visible_to_vba() {
        let source = "Public Function Probe() As String\nDim c As Object\nSet c=Range(\"A2\").FormatConditions(1)\nProbe=CStr(Range(\"A2\").FormatConditions.Count) & \"|\" & CStr(c.Type) & \"|\" & c.Formula1 & \"|\" & CStr(c.Priority) & \"|\" & CStr(c.StopIfTrue) & \"|\" & c.AppliesTo.Address\nEnd Function";
        for (bytes, expected) in [
            (include_bytes!("../../../tests/fixtures/conditional/cell_is.xlsx").as_slice(), "2|1|=50|1|False|$A$2:$A$8"),
            (include_bytes!("../../../tests/fixtures/conditional/expression.xlsx").as_slice(), "1|2|=A2>$B$2|1|False|$A$2:$A$5"),
            (include_bytes!("../../../tests/fixtures/conditional/text_rules.xlsx").as_slice(), "3|9|=NOT(ISERROR(SEARCH(\"apple\",A2)))|1|False|$A$2:$A$7"),
            (include_bytes!("../../../tests/fixtures/conditional/blanks.xlsx").as_slice(), "2|10|=LEN(TRIM(A2))=0|1|False|$A$2:$A$6"),
        ] {
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("Probe"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none());
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, source, Some("Probe"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none());
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened");
        }
    }

