    #[test]
    fn loaded_conditional_settings_survive_save_and_reopen() {
        for (bytes, settings, expected) in [
            (include_bytes!("../../../tests/fixtures/conditional/top10.xlsx").as_slice(), "c.Rank=3: c.TopBottom=0: c.Percent=True: c.StopIfTrue=True", "3|0|True|True"),
            (include_bytes!("../../../tests/fixtures/conditional/duplicates.xlsx").as_slice(), "c.DupeUnique=0: c.StopIfTrue=True", "0|True"),
        ] {
            let read = if expected.starts_with('3') { "CStr(c.Rank) & \"|\" & CStr(c.TopBottom) & \"|\" & CStr(c.Percent) & \"|\" & CStr(c.StopIfTrue)" }
                else { "CStr(c.DupeUnique) & \"|\" & CStr(c.StopIfTrue)" };
            let source = format!("Public Function Change() As String\nDim c As Object\nSet c=Range(\"A2\").FormatConditions(1)\n{settings}\nChange={read}\nEnd Function\nPublic Function ReadRule() As String\nDim c As Object\nSet c=Range(\"A2\").FormatConditions(1)\nReadRule={read}\nEnd Function");
            let original = oxicells_core::parse_xlsx(bytes).unwrap();
            let original_style = original.sheets[0].conditional_rules[0].style.clone();
            let result = execute_workbook_action_in_session(original, &source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            assert_eq!(reopened.sheets[0].conditional_rules[0].style, original_style);
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none());
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
        }
    }

    #[test]
    fn new_conditional_format_and_differential_style_survive_save() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/cell_is.xlsx");
        for add_sheet in [false, true] {
            let source = format!("Public Function Change() As String\n{}\nRange(\"C1\").Value=10: Range(\"C2\").Value=30\nDim c As Object\nSet c=Range(\"C1:C2\").FormatConditions.Add(1,5,20)\nc.Interior.Color=255: c.Font.Bold=True: c.Font.Strikethrough=True\nChange=ReadRule()\nEnd Function\nPublic Function ReadRule() As String\nDim c As Object\nSet c=Range(\"C1\").FormatConditions(1)\nReadRule=CStr(Range(\"C1\").DisplayFormat.Interior.Color) & \"|\" & CStr(Range(\"C2\").DisplayFormat.Interior.Color) & \"|\" & CStr(Range(\"C2\").DisplayFormat.Font.Bold) & \"|\" & CStr(Range(\"C2\").DisplayFormat.Font.Strikethrough) & \"|\" & c.Formula1 & \"|\" & CStr(c.StopIfTrue)\nEnd Function", if add_sheet { "Worksheets.Add" } else { "" });
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            let expected = serde_json::json!({"type":"string", "value":"16777215|255|True|True|=20|True"});
            assert_eq!(serde_json::to_value(&result.result).unwrap(), expected);
            let active = result.active_sheet;
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let saved = editor.save().unwrap();
            let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadRule"), vec![], active, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), expected, "added sheet: {add_sheet}");
        }
    }

