    #[test]
    fn new_and_loaded_data_bars_gain_auto_points_and_preserve_other_rules() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let source = "Public Function AddRule() As String\nDim c As Object\nSet c=Range(\"F2:F6\").FormatConditions.AddDatabar\nAddRule=CStr(c.MinPoint.Type) & \"|\" & CStr(c.MaxPoint.Type)\nEnd Function\nPublic Function AutoRule() As String\nDim c As Object\nSet c=Range(\"F2\").FormatConditions(1)\nc.MinPoint.Modify 6,0\nc.MaxPoint.Modify 7,0\nAutoRule=ReadRule()\nEnd Function\nPublic Function ReadRule() As String\nDim c As Object\nSet c=Range(\"F2\").FormatConditions(1)\nReadRule=CStr(c.MinPoint.Type) & \"|\" & CStr(c.MaxPoint.Type) & \"|\" & c.AppliesTo.Address & \"|\" & CStr(Range(\"B2\").FormatConditions.Count)\nEnd Function";
        let initial = oxicells_core::parse_xlsx(bytes).unwrap();
        let added = execute_workbook_action_in_session(initial, source, Some("AddRule"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(added.error.is_none());
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&added.workbook).unwrap();
        let base = editor.save().unwrap();
        for original in [false, true] {
            let input = if original { &base[..] } else { &bytes[..] };
            let setup = if original { oxicells_core::parse_xlsx(input).unwrap() } else { added.workbook.clone() };
            let result = execute_workbook_action_in_session(setup, source, Some("AutoRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            let expected = serde_json::json!({"type":"string", "value":"6|7|$F$2:$F$6|1"});
            assert_eq!(serde_json::to_value(&result.result).unwrap(), expected);
            let mut editor = oxicells_core::XlsxEditor::new(input).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
            let saved = editor.save().unwrap();
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(&saved).unwrap(), source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
            assert_eq!(serde_json::to_value(&result.result).unwrap(), expected);
        }
    }

