    #[test]
    fn color_scale_threshold_boolean_and_null_match_excel() {
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let source = "Public Function Change() As String\nCells.FormatConditions.Delete\nDim c As Object, p As Object, v As Variant, s As String\nSet c=Range(\"A2:A6\").FormatConditions.AddColorScale(3)\nSet p=c.ColorScaleCriteria(2)\np.Value=True: s=CStr(p.Value) & \"|\"\np.Value=42: s=s & CStr(p.Value) & \"|\"\np.Value=False: s=s & CStr(p.Value) & \"|\"\nOn Error Resume Next\np.Value=v: s=s & CStr(Err.Number) & \"|\" & CStr(p.Value)\nErr.Clear: On Error GoTo 0\nChange=s\nEnd Function\nPublic Function ClearWithNull() As String\nDim p As Object\nSet p=Range(\"A2\").FormatConditions(1).ColorScaleCriteria(2)\np.Value=Null\nClearWithNull=CStr(p.Value)\nEnd Function\nPublic Function ReadRule() As String\nReadRule=CStr(Range(\"A2\").FormatConditions(1).ColorScaleCriteria(2).Value)\nEnd Function";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("Change"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=TRUE|=TRUE|=FALSE|1004|=FALSE"}));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let saved = editor.save().unwrap();
        let reopened = oxicells_core::parse_xlsx(&saved).unwrap();
        let result = execute_workbook_action_in_session(reopened, source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=FALSE"}));
        let result = execute_workbook_action_in_session(result.workbook, source, Some("ClearWithNull"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none(), "{:?}", result.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"="}));
        let mut editor = oxicells_core::XlsxEditor::new(&saved).unwrap(); editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let result = execute_workbook_action_in_session(reopened, source, Some("ReadRule"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"0"}));
    }

