    #[test]
    fn nonfinite_project_state_survives_separate_vba_calls() {
        let source = "Private saved As Variant\nPublic Sub Prime()\nsaved=FV(-2,.5,100,50)\nEnd Sub\nPublic Function Check() As String\nCheck=TypeName(saved) & \":\" & CStr(saved) & \":\" & CStr(saved=0)\nEnd Function";
        let bytes = include_bytes!("../../../tests/fixtures/conditional/visual_rules.xlsx");
        let mut session = None;
        let first = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("Prime"), vec![], 0, failure_context(), &mut session).unwrap();
        assert!(first.error.is_none(), "{:?}", first.error.as_ref().map(|error| &error.message));
        let workbook = serde_json::from_value(serde_json::to_value(first.workbook).unwrap()).unwrap();
        let next = execute_workbook_action_in_session(workbook, source, Some("Check"), vec![], 0, failure_context(), &mut session).unwrap();
        assert!(next.error.is_none(), "{:?}", next.error.as_ref().map(|error| &error.message));
        assert_eq!(serde_json::to_value(&next.result).unwrap(), serde_json::json!({"type":"string", "value":"Double:-nan(ind):True"}));
    }

