    #[test]
    fn vba_reads_and_writes_rectangular_ranges_in_row_major_order() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function FillRange() As Long
               Dim values As Variant
               Dim item As Variant
               Dim total As Long
               Range(\"A1:B2\").Value = 5
               values = Range(\"A1\", \"B2\").Value
               For Each item In values
                 total = total + item
               Next item
               FillRange = total + values(1, 1) + values(2, 2) + UBound(values, 2)
             End Function
             Public Sub WriteArray()
               Dim values(1 To 2, 1 To 2) As Long
               values(1, 1) = 10
               values(1, 2) = 20
               values(2, 1) = 30
               values(2, 2) = 40
               Range(\"C1:D2\").Value = values
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let mut runtime = oxivba_core::Runtime::new(&module).with_host(&mut host);
            assert_eq!(
                runtime.call("FillRange", vec![]).unwrap(),
                Value::Integer(32)
            );
            assert_eq!(runtime.call("WriteArray", vec![]).unwrap(), Value::Empty);
        }
        let rows = &workbook.sheets[0].rows;
        assert!(matches!(rows[0].cells[2].value, CellValue::Number(10.0)));
        assert!(matches!(rows[0].cells[3].value, CellValue::Number(20.0)));
        assert!(matches!(rows[1].cells[2].value, CellValue::Number(30.0)));
        assert!(matches!(rows[1].cells[3].value, CellValue::Number(40.0)));
    }

    #[test]
    fn vba_accesses_worksheets_by_name_and_one_based_index() {
        let mut workbook = workbook();
        workbook.sheets.push(Sheet {
            kind: Default::default(),
            name: "Data".to_string(),
            visibility: Default::default(),
            rows: Vec::new(),
            col_count: 0,
            col_widths: Vec::new(),
            col_custom_widths: Default::default(),
            cached_spills: None,
            pending_used_bounds: None,
            column_width_font: None,
            default_col_width: 0.0,
            default_col_width_explicit: false,
            default_row_height: 15.0,
            default_row_custom: false,
            col_fonts: vec![],
            band_styles: Default::default(),
            normal_font: None,
            first_font: None,
            frozen_rows: 0,
            frozen_cols: 0,
            drawings: Vec::new(),
            comments: Vec::new(),
            threaded_comments: Vec::new(),
            merge_cells: Vec::new(),
            hidden_cols: Vec::new(),
            auto_filter: None,
            declared_range: None,
            tables: Vec::new(),
            unsupported_elements: Vec::new(),
            hyperlinks: Vec::new(),
            protected: false,
            form_controls: Vec::new(),
            validations: Vec::new(),
            conditional_rules: Vec::new(),
            tab_color: None,
            origin_id: None,
        });
        let module = parse_module(
            "Public Function FillSheets() As Long
               Dim ws As Worksheet
               Set ws = Worksheets(\"Data\")
               ws.Range(\"A1\").Value = 40
               Worksheets(2).Cells(2, 1).Value = 2
               FillSheets = ws.Range(\"A1\").Value + ws.Cells(2, 1).Value
             End Function
             Public Function SheetIdentity() As String
               Dim ws As Worksheet
               Set ws = Sheets(2)
               SheetIdentity = ws.Name & \"|\" & ws.Index
             End Function\n",
        )
        .unwrap();
        let (total, identity) = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            let mut runtime = oxivba_core::Runtime::new(&module).with_host(&mut host);
            let total = runtime.call("FillSheets", vec![]).unwrap();
            let identity = runtime.call("SheetIdentity", vec![]).unwrap();
            (total, identity)
        };
        assert_eq!(total, Value::Integer(42));
        assert_eq!(identity, Value::String("Data|2".to_string()));
        assert!(matches!(
            workbook.sheets[1].rows[0].cells[0].value,
            CellValue::Number(value) if value == 40.0
        ));
        assert!(matches!(
            workbook.sheets[1].rows[1].cells[0].value,
            CellValue::Number(value) if value == 2.0
        ));
    }

