        let mut workbook = workbook();
        workbook.sheets[0].rows.push(Row {
            index: 1,
            height: None,
            custom_height: false,
            style_font: None,
            thick_top: false,
            thick_bottom: false,
            hidden: false,
            cells: vec![
                Cell {
                    formula_utf16: None,
                    array_block: None,
                    spill: Default::default(),
                    col: 0,
                    value: CellValue::Number(10.0),
                    style: CellStyle {
                        bold: true,
                        ..CellStyle::default()
                    },
                    formula: None,
                    runs: Vec::new(),
                },
                Cell {
                    formula_utf16: None,
                    array_block: None,
                    spill: Default::default(),
                    col: 1,
                    value: CellValue::String("copied".to_string()),
                    style: CellStyle {
                        bg_color: Some("#ff0000".to_string()),
                        ..CellStyle::default()
                    },
                    formula: None,
                    runs: Vec::new(),
                },
            ],
        });
        let module = parse_module(
            "Public Sub CopyValues()
               Range(\"A1:B1\").Copy Destination:=Range(\"C2\")
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "CopyValues", vec![], &mut host).unwrap();
        }

        let destination = &workbook.sheets[0].rows[1].cells;
        assert!(matches!(destination[0].value, CellValue::Number(10.0)));
        assert!(destination[0].style.bold);
