    #[test]
    fn vba_reads_and_writes_column_widths_and_row_heights() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub ResizeSheet()
               Range(\"A1\").Value = 7
               Columns(2).ColumnWidth = 12.5
               Range(\"C1:D1\").ColumnWidth = 9
               Columns(4).ColumnWidth = 11
               Rows(3).RowHeight = 24
               Range(\"A4\").RowHeight = 18
               Debug.Print Columns(2).ColumnWidth, Range(\"C1:D1\").ColumnWidth, Rows(3).RowHeight, Rows(4).RowHeight
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "ResizeSheet", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        let sheet = &workbook.sheets[0];
        assert_eq!(sheet.col_count, 4);
        // The IR keeps the width the FILE keeps -- the pixels the characters
        // come to, over the standard font's digit (7 here): 12.5 characters
        // are rounded to 93 pixels, stored as 13.28515625.
        assert_eq!(
            sheet.col_widths,
            vec![sheet.default_col_width, 13.28515625, 9.7109375, 11.7109375]
        );
        assert!(matches!(
            sheet.rows[0].cells[0].value,
            CellValue::Number(7.0)
        ));
        assert_eq!(sheet.rows[1].index, 3);
        assert_eq!(sheet.rows[1].height, Some(24.0));
        assert!(sheet.rows[1].cells.is_empty());
        assert_eq!(sheet.rows[2].index, 4);
        assert_eq!(sheet.rows[2].height, Some(18.0));
        assert!(sheet.rows[2].cells.is_empty());
        // A width is kept in whole pixels, so what is read back is the
        // characters those pixels come to: 12.5 of a 7-pixel digit is 92.5
        // pixels, rounded to 93, read back as 12.57. The corresponding
        // Native value is covered by worksheet_cell_width.tsv.
        assert_eq!(debug_output, vec!["12.57\tNull\t24\t18".to_string()]);
    }

    #[test]
    fn vba_inspects_formulas_and_expands_ranges_to_whole_axes() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub InspectRanges()
               Range(\"A1\").Formula = \"=1+1\"
               Range(\"A2\").Formula = \"=A1+1\"
               Range(\"B1\").Value = 3
               Range(\"B3\").EntireRow.RowHeight = 22
               Range(\"C1\").EntireColumn.ColumnWidth = 13
               Debug.Print Range(\"A1:A2\").HasFormula, Range(\"B1:B2\").HasFormula, Range(\"A1:B1\").HasFormula
               Debug.Print Range(\"B3\").EntireRow.Address, Range(\"C1\").EntireColumn.Address, Range(\"C1\").EntireColumn.CountLarge
               Debug.Print Range(\"A1\").Parent.Name, Range(\"A1\").Worksheet.Index
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "InspectRanges", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        let sheet = &workbook.sheets[0];
        assert_eq!(sheet.col_count, 3);
        assert_eq!(sheet.col_widths.len(), 3);
        assert_eq!(sheet.col_widths[2], 13.7109375);
        let row = sheet.rows.iter().find(|row| row.index == 3).unwrap();
        // Excel reports RowHeight 22 but stores ht="21.95" in the saved row.
        assert_eq!(row.height, Some(21.95));
        assert!(row.cells.is_empty());
        assert_eq!(
            debug_output,
            vec![
                "True\tFalse\tNull".to_string(),
                // Excel abbreviates a whole row and a whole column rather than
                // spelling out its far corner — measured, where this
                // expectation had been written the long way without asking.
                "$3:$3	$C:$C	1048576".to_string(),
                "Sheet1\t1".to_string(),
            ]
        );
    }

