    #[test]
    fn vba_formula_utf16_renames_preserve_literals_and_references() {
        let source = r#"Public Sub Probe()
ActiveSheet.Name = "Source"
Range("A1").Value="X": Range("A2").Value=1: Range("A3").Value=2
Set t = ActiveSheet.ListObjects.Add(1, Range("A1:A3"), , 1)
t.Name="OldTable"
Range("C1").Formula = "=SUM(OldTable[X])&""OldTable[X]a" & ChrW(&HD83D) & "b"""
t.Name="NewTable"
Range("C2").Formula = "=Source!A2&""a" & ChrW(&HD83D) & "b"""
ActiveSheet.Name="Renamed"
ThisWorkbook.Names.Add Name:="Rate", RefersTo:="=2"
Range("C3").Formula = "=Rate&""a" & ChrW(&HD83D) & "b"""
ThisWorkbook.Names("Rate").Name="NewRate"
End Sub"#;
        let module = parse_module(source).unwrap();
        let mut workbook = workbook();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        execute_with_host(&module, "Probe", vec![], &mut host).unwrap();
        drop(host);
        for (row, prefix) in [(1, "SUM(NewTable[X])&\"OldTable[X]a"), (2, "Renamed!A2&\"a"), (3, "NewRate&\"a")] {
            let cell = workbook.sheets[0].rows.iter().find(|held| held.index == row).unwrap().cells.iter().find(|cell| cell.col == 2).unwrap();
            let expected: Vec<u16> = prefix.encode_utf16().chain([0xD83D, 98, 34]).collect();
            assert_eq!(cell.formula_units(), Some(expected.as_slice()));
        }
    }

    #[test]
    fn vba_formula_utf16_r1c1_and_fills_preserve_units_references_and_save() {
        let original = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut editor = oxicells_core::XlsxEditor::new(original).unwrap();
        let mut workbook = editor.workbook().clone();
        let source = r#"Public Function Probe() As String
Range("B2").FormulaLocal="=A1&""a" & ChrW(&HD83D) & "b"""
Range("B2:B3").FillDown
Range("D2").FormulaR1C1="=RC[-1]&""a" & ChrW(&HD83D) & "b"""
Range("E4:F5").Formula2R1C1="=RC[-1]&""a" & ChrW(&HD83D) & "b"""
Range("H4:I5").Formula="=A1&""a" & ChrW(&HD83D) & "b"""
Range("B6").Formula="=A5&""a" & ChrW(&HD83D) & "b"""
Range("B5:B6").FillUp
Range("D6").Formula="=C5&""a" & ChrW(&HD83D) & "b"""
Range("D6:E6").FillRight
Range("G6").Formula="=F5&""a" & ChrW(&HD83D) & "b"""
Range("F6:G6").FillLeft
Range("B9").Formula="=A8&""a" & ChrW(&HD83D) & "b"""
Range("B9").AutoFill Destination:=Range("B9:B11")
Probe=Range("B2").FormulaR1C1 & "|" & Range("B2").Formula2R1C1
End Function"#;
        let module = parse_module(source).unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let actual = execute_with_host(&module, "Probe", vec![], &mut host).unwrap();
        let r1c1: Vec<u16> = "=R[-1]C[-1]&\"a".encode_utf16().chain([0xD83D, 98, 34]).collect();
        let expected = r1c1.iter().copied().chain([b'|' as u16]).chain(r1c1.iter().copied()).collect();
        assert_eq!(actual, Value::from_utf16(expected));
        drop(host);
        editor.apply_workbook(&workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        for book in [&workbook, &reopened] {
            for (row, col, reference) in [(3,1,"A2"),(2,3,"C2"),(4,4,"D4"),(4,5,"E4"),(5,4,"D5"),(5,5,"E5"),
                (4,7,"A1"),(4,8,"B1"),(5,7,"A2"),(5,8,"B2"),(5,1,"A4"),(6,4,"D5"),(6,5,"E5"),(10,1,"A9"),(11,1,"A10")] {
                let cell = book.sheets[0].rows.iter().find(|held| held.index == row).unwrap().cells.iter().find(|cell| cell.col == col).unwrap();
                let units: Vec<u16> = format!("{reference}&\"a").encode_utf16().chain([0xD83D,98,34]).collect();
                assert_eq!(cell.formula_units(), Some(units.as_slice()), "row={row} col={col}");
            }
        }
    }

    #[test]
    fn vba_formula_utf16_legacy_getters_keep_literal_units_and_hide_intersections() {
        let module = parse_module(r#"Public Function Probe() As String
Range("B2").Formula="=A1:A2&""a" & ChrW(&HD83D) & "b"""
Range("C4").Value2="A1a" & ChrW(&HD83D) & "b"
Probe=Range("B2").Formula & "|" & Range("B2").Formula2 & "|" & Range("B2").FormulaR1C1 & "|" & Range("C4").FormulaR1C1
End Function"#).unwrap();
        let mut workbook = workbook();
        let actual = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut workbook,0).unwrap()).unwrap();
        let mut expected = Vec::new();
        for (index, prefix) in ["=A1:A2&\"a", "=@A1:A2&\"a", "=R[-1]C[-1]:RC[-1]&\"a"].iter().enumerate() {
            if index != 0 { expected.push(b'|' as u16); }
            expected.extend(prefix.encode_utf16().chain([0xD83D,98,34]));
        }
        expected.extend("|A1a".encode_utf16().chain([0xD83D,98]));
        assert_eq!(actual, Value::from_utf16(expected));
    }

    #[test]
    fn vba_formula_utf16_array_assignment_calculates_and_survives_save() {
        let original = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut editor = oxicells_core::XlsxEditor::new(original).unwrap();
        let mut workbook = editor.workbook().clone();
        let module = parse_module(r#"Public Function Probe() As String
Range("A1").Value=1: Range("A2").Value=2
Range("B2:B3").FormulaArray="=A1:A2&""a" & ChrW(&HD83D) & "b"""
Probe=Range("B2:B3").FormulaArray & "|" & Range("B3").Value & "|" & Range("B2").CurrentArray.Address
End Function"#).unwrap();
        let actual = execute_with_host(&module, "Probe", vec![], &mut WorkbookHost::new(&mut workbook,0).unwrap()).unwrap();
        let expected = "=A1:A2&\"a".encode_utf16().chain([0xD83D,98,34])
            .chain("|2a".encode_utf16()).chain([0xD83D,98]).chain("|$B$2:$B$3".encode_utf16()).collect();
        assert_eq!(actual, Value::from_utf16(expected));
        editor.apply_workbook(&workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let formula: Vec<u16> = "A1:A2&\"a".encode_utf16().chain([0xD83D,98,34]).collect();
        for book in [&workbook,&reopened] {
            for row in [2,3] {
                let cell = book.sheets[0].rows.iter().find(|held| held.index==row).unwrap().cells.iter().find(|held| held.col==1).unwrap();
                assert_eq!(cell.array_block,Some((2,1,3,1)));
                assert_eq!(cell.formula_units(),Some(formula.as_slice()));
                let expected: Vec<u16> = format!("{}a",row-1).encode_utf16().chain([0xD83D,98]).collect();
                assert!(matches!(&cell.value, CellValue::Utf16(units) if *units == expected));
            }
        }
    }

    #[test]
    fn vba_formula_utf16_fills_preserve_manual_caches_and_calculate_automatic_results() {
        for (mode, expected, dependent) in [(-4105, ["2", "2", "3"], 4.0), (-4135, ["1", "1", "1"], 0.0)] {
            let source = format!(r#"Public Sub Probe()
Application.Calculation={mode}
Range("A1").Value=1: Range("A2").Value=2: Range("A3").Value=3
Range("B2").Formula="=A1&""a" & ChrW(&HD83D) & "b"""
Range("D2").Formula="=A1&""a" & ChrW(&HD83D) & "b"""
Range("F1").Formula="=LEN(B3)"
Range("B2:B3").FillDown
Range("D2").AutoFill Destination:=Range("D2:D4")
End Sub"#);
            let mut workbook = workbook();
            let module = parse_module(&source).unwrap();
            execute_with_host(&module,"Probe",vec![],&mut WorkbookHost::new(&mut workbook,0).unwrap()).unwrap();
            for ((row,col), number) in [(3,1),(3,3),(4,3)].into_iter().zip(expected) {
                let cell = workbook.sheets[0].rows.iter().find(|held| held.index==row).unwrap().cells.iter().find(|held| held.col==col).unwrap();
                let units: Vec<u16> = format!("{number}a").encode_utf16().chain([0xD83D,98]).collect();
                assert!(matches!(&cell.value,CellValue::Utf16(actual) if *actual==units), "mode={mode} row={row} col={col} cache={:?}",cell.value);
            }
            let cell = workbook.sheets[0].rows.iter().find(|held|held.index==1).unwrap().cells.iter().find(|held|held.col==5).unwrap();
            assert!(matches!(cell.value,CellValue::Number(value) if value==dependent), "mode={mode} dependent={:?}",cell.value);
        }
    }

