    #[test]
    fn vba_adds_reads_and_finds_threaded_comments_separately_from_notes() {
        let mut workbook = workbook();
        workbook.sheets[0].threaded_comments.push(oxicells_core::ir::ThreadedComment {
                utf16_text: None,
            cell: (8, 4),
            id: "loaded-thread".to_string(),
            parent_id: None,
            person_id: "person-a".to_string(),
            person_name: "Excel User".to_string(),
            person_provider_id: "Windows Live".to_string(),
            person_user_id: "user-hash".to_string(),
            date: "2026-10-23T13:55:31Z".to_string(),
            text: "loaded needle".to_string(),
            resolved: false,
        });
        let module = parse_module(
            "Public Sub FindThreadedComments()
               Set added = Range(\"C5\").AddCommentThreaded(\"thread needle\")
               added.Resolved = True
               Debug.Print added.Resolved
               Debug.Print Range(\"C5:D6\").CommentThreaded.Text, Range(\"D8:E9\").CommentThreaded Is Nothing
               Debug.Print ActiveSheet.CommentsThreaded.Count, ActiveSheet.CommentsThreaded.Item(1).Text, ActiveSheet.CommentsThreaded(2).Text
               Debug.Print ActiveSheet.CommentsThreaded.Item(Index:=1).Text
               Debug.Print ActiveSheet.CommentsThreaded(Index:=2).Text
               Set threadCollection = ActiveSheet.CommentsThreaded
               Debug.Print threadCollection(1).Text, threadCollection._Default(2).Text
               For Each threadItem In ActiveSheet.CommentsThreaded
                 Debug.Print threadItem.Text
               Next
               Debug.Print added.Author.Name, IsDate(added.Date)
               Debug.Print added.Author.ProviderID, added.Author.UserID
               Debug.Print added.Next.Text, IsNull(added.Previous)
               Debug.Print TypeName(added), added.Text, added.Parent.Address(False, False)
               added.Resolved = False
               Set reply = added.AddReply(\"reply needle\")
               Set reply2 = reply.AddReply(\"second reply\")
               Debug.Print TypeName(reply), reply.Text, reply.Parent.Text, added.Replies.Count, added.Replies.Item(1).Text, added.Replies.Item(2).Text, reply.Replies.Count
               Set replyCollection = added.Replies
               Debug.Print replyCollection(1).Text, replyCollection._Default(2).Text, replyCollection.Parent.Text
               Debug.Print replyCollection.Item(Index:=1).Text
               For Each replyItem In replyCollection
                 Debug.Print replyItem.Text
               Next
               Debug.Print reply.Next.Text, IsNull(reply.Previous), IsNull(reply2.Next)
               Set threaded = Range(\"A1\").Find(What:=\"thread needle\", After:=Range(\"A1\"), LookIn:=xlCommentsThreaded, LookAt:=xlWhole)
               Set legacy = Range(\"A1\").Find(What:=\"thread needle\", After:=Range(\"A1\"), LookIn:=xlComments, LookAt:=xlWhole)
               Debug.Print threaded.Address(False, False), legacy Is Nothing, Range(\"A1\").Worksheet.UsedRange.Address(False, False)
               Range(\"C5\").CommentThreaded.Text \"edited needle\"
               Set edited = Range(\"A1\").Find(What:=\"edited needle\", After:=Range(\"A1\"), LookIn:=xlCommentsThreaded, LookAt:=xlWhole)
               Debug.Print edited.Address(False, False)
               Set replyFound = Range(\"A1\").Find(What:=\"reply needle\", After:=Range(\"A1\"), LookIn:=xlCommentsThreaded, LookAt:=xlWhole)
               Debug.Print replyFound.Address(False, False)
               Set loaded = Range(\"A1\").Find(What:=\"loaded needle\", After:=Range(\"A1\"), LookIn:=xlCommentsThreaded, LookAt:=xlWhole)
               Debug.Print loaded.Address(False, False), Range(\"E9\").CommentThreaded.Text
               Debug.Print loaded.CommentThreaded.Author.ProviderID, loaded.CommentThreaded.Author.UserID, IsNull(loaded.CommentThreaded.Next), loaded.CommentThreaded.Previous.Text
               Range(\"E9\").CommentThreaded.Text \"edited loaded\"
               Set loadedEdit = Range(\"A1\").Find(What:=\"edited loaded\", After:=Range(\"A1\"), LookIn:=xlCommentsThreaded, LookAt:=xlWhole)
               Debug.Print loadedEdit.Address(False, False)
               added.Resolved = True
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "FindThreadedComments", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                "True".to_string(),
                "thread needle\tTrue".to_string(),
                "2\tthread needle\tloaded needle".to_string(),
                "thread needle".to_string(),
                "loaded needle".to_string(),
                "thread needle\tloaded needle".to_string(),
                "thread needle".to_string(),
                "loaded needle".to_string(),
                "User\tTrue".to_string(),
                "None\tUser".to_string(),
                "loaded needle\tTrue".to_string(),
                "CommentThreaded\tthread needle\tC5".to_string(),
                "CommentThreaded\treply needle\tthread needle\t2\treply needle\tsecond reply\t0".to_string(),
                "reply needle\tsecond reply\tthread needle".to_string(),
                "reply needle".to_string(),
                "reply needle".to_string(),
                "second reply".to_string(),
                "second reply\tTrue\tTrue".to_string(),
                "C5\tTrue\tC5:E9".to_string(),
                "C5".to_string(),
                "C5".to_string(),
                "E9\tloaded needle".to_string(),
                "Windows Live\tuser-hash\tTrue\tedited needle".to_string(),
                "E9".to_string(),
            ]
        );
        assert_eq!(workbook.sheets[0].threaded_comments[0].text, "edited loaded");
        assert_eq!(workbook.sheets[0].threaded_comments[1].cell, (4, 2));
        assert_eq!(workbook.sheets[0].threaded_comments[1].text, "edited needle");
        assert!(workbook.sheets[0].threaded_comments[1].resolved);
        assert_eq!(workbook.sheets[0].threaded_comments[2].parent_id.as_deref(), Some(workbook.sheets[0].threaded_comments[1].id.as_str()));
        assert_eq!(workbook.sheets[0].threaded_comments[3].parent_id.as_deref(), Some(workbook.sheets[0].threaded_comments[1].id.as_str()));
    }

    #[test]
    fn threaded_replies_are_ordered_by_timestamp() {
        let mut workbook = workbook();
        workbook.sheets[0].threaded_comments.extend([
            oxicells_core::ir::ThreadedComment {
                utf16_text: None,
                cell: (0, 0), id: "root-id".into(), parent_id: None, person_id: "p1".into(),
                person_name: "User".into(), person_provider_id: "None".into(), person_user_id: "User".into(),
                date: "2026-10-24T09:00:00Z".into(), text: "root".into(), resolved: false,
            },
            oxicells_core::ir::ThreadedComment {
                utf16_text: None,
                cell: (0, 0), id: "later-id".into(), parent_id: Some("root-id".into()), person_id: "p1".into(),
                person_name: "User".into(), person_provider_id: "None".into(), person_user_id: "User".into(),
                date: "2026-10-24T09:02:00Z".into(), text: "later".into(), resolved: false,
            },
            oxicells_core::ir::ThreadedComment {
                utf16_text: None,
                cell: (0, 0), id: "earlier-id".into(), parent_id: Some("root-id".into()), person_id: "p1".into(),
                person_name: "User".into(), person_provider_id: "None".into(), person_user_id: "User".into(),
                date: "2026-10-24T09:01:00Z".into(), text: "earlier".into(), resolved: false,
            },
        ]);
        let module = parse_module(
            "Public Sub ReadRepliesByTime()
               Set root = ActiveSheet.CommentsThreaded(1)
               Debug.Print root.Replies.Count, root.Replies(1).Text, root.Replies(2).Text, root.Replies(1).Next.Text, root.Replies(2).Previous.Text
             End Sub\n",
        ).unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "ReadRepliesByTime", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(debug_output, vec!["2\tearlier\tlater\tlater\tearlier"]);
    }

    #[cfg(not(target_arch = "wasm32"))]
    #[test]
    fn threaded_comment_date_parses_offsets_and_fractional_seconds() {
        let utc = threaded_comment_date_serial_utc("2026-10-24T09:01:00.250Z").unwrap();
        let offset = threaded_comment_date_serial_utc("2026-10-24T11:01:00.25+02:00").unwrap();
        let later = threaded_comment_date_serial_utc("2026-10-24T09:01:00.5Z").unwrap();

        assert!((utc - offset).abs() < 1e-9);
        assert!((later - utc - 0.25 / 86_400.0).abs() < 1e-9);
        assert!(threaded_comment_date_serial_utc("2026-13-24T09:01:00Z").is_none());
        assert!(threaded_comment_date_serial_utc("2026-10-24T09:01:00+15:00").is_none());
    }

