    #[test]
    fn ole_objects_add_creates_a_package_server_without_a_filename() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_svg.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\ole-original.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: Vec::new(),
        });
        let source = r#"Public Sub AddEmptyPackages()
            Set omitted = ActiveSheet.OLEObjects.Add(ClassType:="Package")
            Set hiddenIcon = ActiveSheet.OLEObjects.Add(ClassType:="Package", DisplayAsIcon:=False)
            Set displayedIcon = ActiveSheet.OLEObjects.Add(ClassType:="Package", DisplayAsIcon:=True, Left:=10, Top:=20, Width:=60, Height:=70)
            Debug.Print CStr(ActiveSheet.OLEObjects.Count)
            ActiveWorkbook.SaveCopyAs "C:\work\ole-empty-packages.xlsx"
        End Sub"#;
        let outcome = execute_workbook_vba(book, source, "AddEmptyPackages", vec![], 0, context).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["3"]);
        let saved = outcome.files.iter().find(|file| file.path.ends_with("ole-empty-packages.xlsx")).unwrap();
        let reopened = oxicells_core::parse_xlsx(&saved.bytes).unwrap();
        let ole = reopened.sheets[0].drawings.iter().filter(|drawing| drawing.ole_prog_id.is_some()).collect::<Vec<_>>();
        assert_eq!(ole.len(), 3);
        assert_eq!(ole.iter().map(|drawing| drawing.ole_display_as_icon).collect::<Vec<_>>(), [Some(false), Some(false), Some(true)]);

        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(&saved.bytes)).unwrap();
        let mut worksheet_xml = String::new();
        std::io::Read::read_to_string(&mut archive.by_name("xl/worksheets/sheet1.xml").unwrap(), &mut worksheet_xml).unwrap();
        assert_eq!(worksheet_xml.matches("dvAspect=\"DVASPECT_ICON\"").count(), 1);
        let mut empty_icon = Vec::new();
        std::io::Read::read_to_end(&mut archive.by_name("xl/media/image1.emf").unwrap(), &mut empty_icon).unwrap();
        assert_eq!(empty_icon, include_bytes!("../../../crates/oxicells-core/src/data/ole_package_empty_icon.emf"));

        let mut embedded_packages = 0;
        for index in 0..archive.len() {
            let part_name = archive.by_index(index).unwrap().name().to_owned();
            if !part_name.starts_with("xl/embeddings/oleObject") { continue; }
            let mut embedded = Vec::new();
            std::io::Read::read_to_end(&mut archive.by_index(index).unwrap(), &mut embedded).unwrap();
            let compound = cfb::CompoundFile::open(std::io::Cursor::new(&embedded)).unwrap();
            assert_eq!(compound.root_entry().clsid(), &uuid::uuid!("0003000c-0000-0000-c000-000000000046"));
            assert!(compound.walk().all(|entry| !entry.is_stream()), "ClassType=Package without Filename creates an empty CFB storage");
            embedded_packages += 1;
        }
        assert_eq!(embedded_packages, 3);
        if let Some(path) = std::env::var_os("OXI_EMPTY_PACKAGE_OUTPUT") {
            std::fs::write(path, &saved.bytes).unwrap();
        }
    }

    #[test]
    fn ole_objects_add_creates_a_blank_word_document_server() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/scale_picture_original_svg.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\ole-original.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: Vec::new(),
        });
        let source = r#"Public Sub AddWordDocuments()
            Set plain = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document", Link:="True")
            Set icon = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", DisplayAsIcon:=True, Left:=10, Top:=20, Width:=100, Height:=50)
            Set placed = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Left:=10, Height:=20)
            Set sized = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Width:=50)
            Set negative = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Width:=-10)
            Set shifted = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Left:="0.25", Top:="10", Width:="50")
            Set flagWidth = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", Width:=True)
            Set stringIcon = ActiveSheet.OLEObjects.Add(ClassType:="Word.Document.12", DisplayAsIcon:="True")
            Debug.Print CStr(ActiveSheet.OLEObjects.Count) & "/" & plain.progId & "/" & CStr(plain.Width) & "/" & CStr(plain.Height)
            Debug.Print icon.progId & "/" & CStr(icon.Left) & "/" & CStr(icon.Top) & "/" & CStr(icon.Width) & "/" & CStr(icon.Height)
            Debug.Print CStr(placed.Left) & "/" & CStr(placed.Width) & "/" & CStr(placed.Height)
            Debug.Print CStr(sized.Left) & "/" & CStr(sized.Width) & "/" & CStr(sized.Height)
            Debug.Print CStr(negative.Left) & "/" & CStr(negative.Width) & "/" & CStr(negative.Height)
            Debug.Print CStr(shifted.Left) & "/" & CStr(shifted.Top) & "/" & CStr(shifted.Width) & "/" & CStr(shifted.Height)
            Debug.Print CStr(flagWidth.Width) & "/" & CStr(flagWidth.Height)
            Debug.Print CStr(stringIcon.Width) & "/" & CStr(stringIcon.Height)
            ActiveWorkbook.SaveCopyAs "C:\\work\\ole-word-documents.xlsx"
        End Sub"#;
        let outcome = execute_workbook_vba(book, source, "AddWordDocuments", vec![], 0, context).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, [
            "8/Word.Document.12/441.75/24.75",
            "Word.Document.12/9.75/19.5/72/60.75",
            "9.75/0.75/24.75",
            "0/48.75/24.75",
            "0/9.75/24.75",
            "0/9.75/50.25/24.75",
            "1.5/24.75",
            "72/60.75",
        ]);
        let saved = outcome.files.iter().find(|file| file.path.ends_with("ole-word-documents.xlsx")).unwrap();
        if let Some(path) = std::env::var_os("OXI_WORD_DOCUMENT_OUTPUT") {
            std::fs::write(path, &saved.bytes).unwrap();
        }
        let reopened = oxicells_core::parse_xlsx(&saved.bytes).unwrap();
        let ole = reopened.sheets[0].drawings.iter().filter(|drawing| drawing.ole_prog_id.is_some()).collect::<Vec<_>>();
        assert_eq!(ole.len(), 8);
        assert!(ole.iter().all(|drawing| drawing.ole_prog_id.as_deref() == Some("Word.Document.12")));
        assert_eq!(ole.iter().map(|drawing| drawing.ole_display_as_icon).collect::<Vec<_>>(), [Some(false), Some(true), Some(false), Some(false), Some(false), Some(false), Some(false), Some(true)]);

        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(&saved.bytes)).unwrap();
        let mut matching_word_packages = 0;
        for index in 0..archive.len() {
            let mut part = archive.by_index(index).unwrap();
            if part.name().starts_with("xl/embeddings/") && part.name().ends_with(".docx") {
                let mut word_docx = Vec::new();
                std::io::Read::read_to_end(&mut part, &mut word_docx).unwrap();
                if word_docx == include_bytes!("data/word_document_empty.docx") {
                    matching_word_packages += 1;
                }
            }
        }
        assert_eq!(matching_word_packages, 4);
        let mut sheet_rels = String::new();
        let mut worksheet = String::new();
        for index in 0..archive.len() {
            let mut part = archive.by_index(index).unwrap();
            let part_name = part.name().to_owned();
            if part_name.starts_with("xl/worksheets/_rels/") && part_name.ends_with(".xml.rels") {
                let mut contents = String::new();
                std::io::Read::read_to_string(&mut part, &mut contents).unwrap();
                if contents.contains("/relationships/package") { sheet_rels.push_str(&contents); }
            } else if part_name.starts_with("xl/worksheets/") && part_name.ends_with(".xml") {
                let mut contents = String::new();
                std::io::Read::read_to_string(&mut part, &mut contents).unwrap();
                if contents.contains("Word.Document.12") { worksheet.push_str(&contents); }
            }
        }
        assert_eq!(sheet_rels.matches("/relationships/package").count(), 8);
        assert!(!sheet_rels.contains("/relationships/oleObject"));
        assert_eq!(worksheet.matches("progId=\"Word.Document.12\"").count(), 8);
        assert_eq!(worksheet.matches("dvAspect=\"DVASPECT_ICON\"").count(), 2);

        let mut sized_packages = [0; 4];
        for index in 0..archive.len() {
            let mut part = archive.by_index(index).unwrap();
            if part.name().starts_with("xl/embeddings/") && part.name().ends_with(".docx") {
                let mut word_docx = Vec::new();
                std::io::Read::read_to_end(&mut part, &mut word_docx).unwrap();
                let mut word_archive = zip::ZipArchive::new(std::io::Cursor::new(word_docx)).unwrap();
                let mut document_xml = String::new();
                std::io::Read::read_to_string(
                    &mut word_archive.by_name("word/document.xml").unwrap(),
                    &mut document_xml,
                )
                .unwrap();
                if document_xml.contains("w:w=\"4380\" w:h=\"15840\"") {
                    sized_packages[0] += 1;
                }
                if document_xml.contains("w:w=\"3600\" w:h=\"15840\"") {
                    sized_packages[1] += 1;
                }
                if document_xml.contains("w:w=\"4410\" w:h=\"15840\"") {
                    sized_packages[2] += 1;
                }
                if document_xml.contains("w:w=\"3435\" w:h=\"15840\"") {
                    sized_packages[3] += 1;
                }
            }
        }
        assert_eq!(sized_packages, [1, 1, 1, 1]);
    }

