    #[test]
    fn deleting_nested_group_leaf_persists_flat_excel_group() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/grouped_shapes_nested_rotated.xlsx");
        let book = oxicells_core::parse_xlsx(bytes).unwrap();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(bytes.to_vec()),
            full_name: Some("C:\\work\\nested.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub RemoveNestedLeaf()
            ActiveSheet.Shapes("ChildA").Delete
            Debug.Print ActiveSheet.Shapes.Count & "/" & ActiveSheet.Shapes(1).Name & "/" & ActiveSheet.Shapes(1).GroupItems.Count
            Debug.Print Format(ActiveSheet.Shapes(1).Left, "0.000") & "/" & Format(ActiveSheet.Shapes(1).Top, "0.000") & "/" & Format(ActiveSheet.Shapes(1).Width, "0.000") & "/" & Format(ActiveSheet.Shapes(1).Height, "0.000")
            Debug.Print ActiveSheet.Shapes("ChildB").Name & "/" & ActiveSheet.Shapes("ChildC").Name
            ActiveWorkbook.SaveCopyAs "C:\work\nested-delete.xlsx"
        End Sub"#;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("RemoveNestedLeaf"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert_eq!(outcome.debug_output, ["1/OuterGroup/2", "37.990/17.500/60.000/20.000", "ChildB/ChildC"]);
        assert_eq!(outcome.files.len(), 1);
        if let Some(path) = std::env::var_os("OXI_NESTED_GROUP_DELETE_OUTPUT") {
            std::fs::write(path, &outcome.files[0].bytes).unwrap();
        }
        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        let survivors = saved.sheets[0].drawings.iter()
            .filter(|drawing| drawing.name.as_deref() != Some("OuterGroup"))
            .collect::<Vec<_>>();
        assert_eq!(survivors.len(), 2);
        assert!(saved.sheets[0].drawings.iter().all(|drawing| drawing.name.as_deref() != Some("ChildA")));
        assert!(survivors.iter().all(|drawing| drawing.grouped && drawing.group_name.as_deref() == Some("OuterGroup")));
        assert_eq!(survivors.iter().map(|drawing| drawing.name.as_deref()).collect::<Vec<_>>(), [Some("ChildB"), Some("ChildC")]);
        let mut archive = zip::ZipArchive::new(std::io::Cursor::new(&outcome.files[0].bytes)).unwrap();
        let mut drawing_xml = String::new();
        std::io::Read::read_to_string(&mut archive.by_name("xl/drawings/drawing1.xml").unwrap(), &mut drawing_xml).unwrap();
        assert_eq!(drawing_xml.matches("<xdr:grpSp>").count(), 1, "{drawing_xml}");
        assert!(!drawing_xml.contains("InnerGroup"), "{drawing_xml}");
    }

