    #[test]
    fn shape_colorformat_uses_the_workbooks_custom_theme_palette() {
        let base = include_bytes!("../../../tests/fixtures/basic_test.xlsx");
        let mut editor = oxicells_core::XlsxEditor::new(base).unwrap();
        let mut source_workbook = editor.workbook().clone();
        source_workbook.sheets[0].drawings.push(oxicells_core::ir::Drawing {
            name: Some("Rectangle 1".into()),
            ole_prog_id: None,
            ole_source_name: None,
            ole_clone_position: None,
            ole_embedded_package: None,
            ole_package_is_empty: None,
            ole_clone_visible: None,
            ole_placement: None,
            ole_type: None,
            ole_display_as_icon: None,
            ole_auto_load: None,
            ole_enabled: None,
            ole_locked: None,
            ole_print_object: None,
            ole_shadow: None,
            ole_on_action: None,
            ole_border_color: None,
            ole_border_weight: None,
            ole_interior_color: None,
            from: oxicells_core::ir::Anchor { col: 0, col_off: 0, row: 0, row_off: 0 },
            to: Some(oxicells_core::ir::Anchor { col: 2, col_off: 0, row: 2, row_off: 0 }),
            extent: Some((1_000_000, 600_000)),
            kind: oxicells_core::ir::DrawingKind::Shape(oxicells_core::ir::Shape {
                geometry: "rect".into(), text_box: false, fill: Some("112233".into()), fill_theme: None,
                fill_legacy_color_index: None, fill_brightness: None, line: None,
                adjusts: Vec::new(), path: None, flip_h: false, flip_v: false, rotation: 0, text: None,
            }),
            frame: None,
            grouped: false,
            group_name: None,
            group_rotation: 0,
            group_transform: None,
            group_child_transform: None,
            group_nested: false,
        });
        editor.apply_workbook(&source_workbook).unwrap();
        let package = editor.save().unwrap();
        let mut book = oxicells_core::parse_xlsx(&package).unwrap();
        // The Office DrawingML order is dk1, lt1, dk2, lt2, then Accent1.
        // COM's RGB long 0x0066CC is BGR-packed; DrawingML stores the same
        // visible color as RRGGBB `CC6600`.
        book.theme_colors[4] = "CC6600".into();
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(package), full_name: Some("C:\\work\\custom-theme.xlsx".into()),
            read_only: Some(true), folders: vec!["C:\\work".into()], files: vec![],
        });
        let source = r#"Public Sub ReadCustomTheme()
            With ActiveSheet.Shapes("Rectangle 1").Fill.ForeColor
                .ObjectThemeColor = 5
                .Brightness = 0.4
                Debug.Print .ObjectThemeColor & "/" & .Brightness & "/" & .RGB
                Debug.Print "fill theme SchemeColor=" & .SchemeColor
            End With
            Dim fresh As Object
            Set fresh = ActiveSheet.Shapes.AddShape(1, 20, 20, 100, 50)
            Debug.Print fresh.Fill.ForeColor.RGB & "/" & fresh.Fill.ForeColor.ObjectThemeColor
            fresh.Fill.ForeColor.RGB = 255
            Debug.Print fresh.Fill.ForeColor.SchemeColor
            fresh.Fill.ForeColor.RGB = 3700878
            Debug.Print "fill arbitrary RGB SchemeColor=" & fresh.Fill.ForeColor.RGB & "/" & fresh.Fill.ForeColor.SchemeColor
            Debug.Print "fill RGB Type/Theme=" & fresh.Fill.ForeColor.Type & "/" & fresh.Fill.ForeColor.ObjectThemeColor
            Debug.Print fresh.Line.ForeColor.RGB & "/" & fresh.Line.ForeColor.ObjectThemeColor & "/" & fresh.Line.ForeColor.Brightness
            fresh.Line.ForeColor.RGB = 255
            Debug.Print "line RGB SchemeColor=" & fresh.Line.ForeColor.SchemeColor
            fresh.Line.ForeColor.RGB = 3700878
            Debug.Print "line arbitrary RGB SchemeColor=" & fresh.Line.ForeColor.SchemeColor
            Debug.Print "line RGB Type/Theme=" & fresh.Line.ForeColor.Type & "/" & fresh.Line.ForeColor.ObjectThemeColor
            fresh.Line.Pattern = 1
            fresh.Line.ForeColor.ObjectThemeColor = 5
            fresh.Line.ForeColor.Brightness = 0.4
            fresh.Line.BackColor.ObjectThemeColor = 5
            fresh.Line.BackColor.Brightness = 0.4
            Debug.Print "line theme SchemeColor=" & fresh.Line.ForeColor.SchemeColor
            Debug.Print "line back theme SchemeColor=" & fresh.Line.BackColor.SchemeColor
            Debug.Print fresh.Line.ForeColor.RGB & "/" & fresh.Line.ForeColor.Brightness
            Debug.Print fresh.Line.BackColor.RGB & "/" & fresh.Line.BackColor.Brightness
            fresh.TextFrame2.TextRange.Text = "x"
            fresh.TextFrame2.TextRange.Font.Fill.ForeColor.ObjectThemeColor = 5
            fresh.TextFrame2.TextRange.Font.Fill.ForeColor.Brightness = 0.4
            Debug.Print fresh.TextFrame2.TextRange.Font.Fill.ForeColor.RGB & "/" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.Brightness
            Debug.Print "text theme SchemeColor=" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.SchemeColor
            fresh.TextFrame2.TextRange.Font.Fill.ForeColor.RGB = 255
            Debug.Print "text RGB SchemeColor=" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.SchemeColor
            fresh.TextFrame2.TextRange.Font.Fill.ForeColor.RGB = 3700878
            Debug.Print "text arbitrary RGB SchemeColor=" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.SchemeColor
            Debug.Print "text RGB Type/Theme=" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.Type & "/" & fresh.TextFrame2.TextRange.Font.Fill.ForeColor.ObjectThemeColor
        End Sub"#;
        let mut session = None;
        let outcome = execute_workbook_action_in_session(
            book, source, Some("ReadCustomTheme"), vec![], 0, context, &mut session,
        ).unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        assert!(outcome.debug_output.iter().any(|line| line == "5/0.4/4695039"), "{:?}", outcome.debug_output);
        for label in ["fill theme", "line theme", "line back theme", "text theme"] {
            assert!(outcome.debug_output.iter().any(|line| line == &format!("{label} SchemeColor=52")), "{:?}", outcome.debug_output);
        }
        assert!(outcome.debug_output.iter().any(|line| line == "26316/5"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "10"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "fill arbitrary RGB SchemeColor=3700878/51"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "line RGB SchemeColor=10"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "line arbitrary RGB SchemeColor=51"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "text RGB SchemeColor=10"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "text arbitrary RGB SchemeColor=51"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "fill RGB Type/Theme=1/0"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "line RGB Type/Theme=1/0"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "text RGB Type/Theme=1/0"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().any(|line| line == "10069/5/0"), "{:?}", outcome.debug_output);
        assert!(outcome.debug_output.iter().filter(|line| line.as_str() == "4695039/0.4").count() >= 3, "{:?}", outcome.debug_output);
    }

