    #[test]
    fn vba_continues_the_previous_range_search() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub ContinueSearch()
               Range(\"A1\").Value = \"hit\"
               Range(\"A3\").Value = \"hit\"
               Set first = Range(\"A1:A3\").Find(What:=\"hit\", LookIn:=xlValues, LookAt:=xlWhole, SearchOrder:=xlByRows, SearchDirection:=xlNext, MatchCase:=False)
               Set following = Range(\"A1:A3\").FindNext(After:=first)
               Set preceding = Range(\"A1:A3\").FindPrevious(following)
               Set wrapped = Range(\"A1:A3\").FindNext()
               Debug.Print first.Address(False, False), following.Address(False, False), preceding.Address(False, False), wrapped.Address(False, False)
               Set missing = Range(\"A1:A3\").Find(\"absent\")
               Set stillMissing = Range(\"A1:A3\").FindNext()
               Debug.Print missing Is Nothing, stillMissing Is Nothing
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "ContinueSearch", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        assert_eq!(
            debug_output,
            vec!["A3\tA1\tA3\tA1".to_string(), "True\tTrue".to_string(),]
        );
    }

    #[test]
