    #[test]
    fn workbook_colors_gets_sets_and_drives_colorformat_scheme_color() {
        let package = include_bytes!("../../oxicells-core/tests/fixtures/wrapped.xlsx");
        let mut context = failure_context();
        context.file_context = Some(file_io::FileContext {
            package_bytes: Some(package.to_vec()),
            full_name: Some("C:\\work\\source.xlsx".into()),
            read_only: Some(true),
            folders: vec!["C:\\work".into()],
            files: vec![],
        });
        let source = r#"Public Sub WorkbookColors()
            Dim palette As Variant
            palette = ThisWorkbook.Colors
            Debug.Print LBound(palette)
            Debug.Print UBound(palette)
            Debug.Print palette(13)
            ThisWorkbook.Colors(3) = 4402555
            ThisWorkbook.Colors(20) = 255
            Debug.Print ThisWorkbook.Colors(20)
            ThisWorkbook.Colors(19) = 1.6
            Debug.Print ThisWorkbook.Colors(19)
            Set box = ActiveSheet.Shapes.AddShape(1, 1, 1, 10, 10)
            box.Fill.ForeColor.RGB = 255
            Debug.Print box.Fill.ForeColor.SchemeColor
            palette = ThisWorkbook.Colors
            palette(21) = 4402555
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(21)
            ReDim palette(0 To 54)
            For i = 0 To 54
                palette(i) = 100000 + i
            Next i
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(1)
            Debug.Print ThisWorkbook.Colors(55)
            Debug.Print ThisWorkbook.Colors(56)
            ReDim palette(1 To 57)
            For i = 1 To 57
                palette(i) = 200000 + i
            Next i
            ThisWorkbook.Colors = palette
            Debug.Print ThisWorkbook.Colors(56)
            ReDim palette(1 To 7, 1 To 8)
            On Error Resume Next
            ThisWorkbook.Colors = palette
            Debug.Print Err.Number
            On Error GoTo 0
            ThisWorkbook.SaveCopyAs "C:\work\colors.xlsx"
        End Sub"#;
        let outcome = execute_workbook_vba(
            oxicells_core::parse_xlsx(package).unwrap(),
            source,
            "WorkbookColors",
            vec![],
            0,
            context,
        )
        .unwrap();
        assert!(outcome.error.is_none(), "{:?}", outcome.error.as_ref().map(|error| &error.message));
        for expected in ["1", "56", "8388736", "255", "1", "27", "4402555", "100000", "100054", "0", "200056", "1004"] {
            assert!(
                outcome.debug_output.iter().any(|line| line == expected),
                "missing Workbook.Colors result {expected}: {:?}",
                outcome.debug_output
            );
        }
        assert_eq!(outcome.workbook.indexed_colors.len(), 64);
        assert_eq!(outcome.workbook.indexed_colors[8], "410D03");
        assert_eq!(outcome.workbook.indexed_colors[62], "770D03");
        assert_eq!(outcome.workbook.indexed_colors[63], "780D03");
        assert_eq!(outcome.files.len(), 1);
        let saved = oxicells_core::parse_xlsx(&outcome.files[0].bytes).unwrap();
        assert_eq!(saved.indexed_colors[8], "410D03");
        assert_eq!(saved.indexed_colors[62], "770D03");
        assert_eq!(saved.indexed_colors[63], "780D03");
    }

    #[test]
    fn colorindex_uses_current_palette_for_exact_colors_and_builtin_for_nearby_rgb() {
        let mut palette = COLOUR_PALETTE;
        palette[2] = 14_474_460;
        palette[3] = 1_357_599;
        assert_eq!(nearest_palette_index_in(14_474_460, &palette), 3);
        assert_eq!(nearest_palette_index_in(14_474_461, &palette), 24);
        assert_eq!(nearest_palette_index_in(14_474_459, &palette), 24);
        assert_eq!(nearest_palette_index_in(255, &palette), -5);
        assert_eq!(nearest_palette_index_in(65_280, &palette), -4);

        // Excel returns the first eight legacy indices minus eight when their
        // colors have been removed from the current palette.
        let mut without_system_colours = COLOUR_PALETTE;
        for index in [0, 1, 2, 3, 4, 31, 5, 26, 6, 25, 7, 27] {
            without_system_colours[index] = 16_000_000 - index as i64 * 1_000;
        }
        for (index, colour) in COLOUR_PALETTE[..8].iter().enumerate() {
            assert_eq!(
                nearest_palette_index_in(*colour, &without_system_colours),
                index as i64 - 7,
                "missing built-in palette index {}",
                index + 1
            );
        }
    }

    /// A colour the FILE gave a cell is the colour the macro sees.
    ///
    /// The file writes six hex digits with nothing in front, and that is what
    /// the IR keeps. A macro used to see white where the file said red,
    /// because the host wrote its own colours with a `#` and read only that
    /// form back.
    #[test]
    fn vba_sees_the_colour_the_file_gave_a_cell() {
        let mut workbook = workbook();
        workbook.sheets[0].rows.push(Row {
            index: 1,
            cells: vec![Cell {
                formula_utf16: None,
                array_block: None,
                spill: Default::default(),
                col: 0,
                value: CellValue::Empty,
                style: CellStyle {
                    bg_color: Some("FF0000".to_string()),
                    font_color: Some("00FF00".to_string()),
                    ..CellStyle::default()
                },
                formula: None,
                runs: Vec::new(),
            }],
            height: None,
            custom_height: false,
            style_font: None,
            thick_top: false,
            thick_bottom: false,
            hidden: false,
        });
        let module = parse_module(
            "Public Function Seen() As String
               Seen = Range(\"A1\").Interior.Color & \"|\" & Range(\"A1\").Font.Color & \"|\" & _
                 Range(\"A1\").Interior.ColorIndex
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Seen", vec![], &mut host).unwrap()
        };
        assert_eq!(result, Value::String("255|65280|3".to_string()));

        // And what the macro writes is written the same way, so the file and
        // the page both read it back.
        let module = parse_module(
            "Public Sub Paint()\n  Range(\"B1\").Interior.Color = 255\nEnd Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Paint", vec![], &mut host).unwrap();
        }
        let painted = workbook.sheets[0]
            .rows
            .iter()
            .find(|row| row.index == 1)
            .and_then(|row| row.cells.iter().find(|cell| cell.col == 1))
            .and_then(|cell| cell.style.bg_color.clone());
        assert_eq!(painted.as_deref(), Some("FF0000"));
    }

    /// `ColorIndex` names a colour by the nearest of Excel's 56.
    ///
    /// Every answer was asked of Excel: index 3 is red (255) and 5 is blue
    /// (16711680); an off-palette colour is called by the NEAREST entry, so
    /// 12345 answers 52; a cell with no fill answers `xlNone` and one that
    /// names no writing colour answers 1; and a block whose cells disagree
    /// answers Null.
    #[test]
    fn vba_names_a_colour_by_the_nearest_of_the_fifty_six() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Named() As String
               Range(\"A1\").Interior.ColorIndex = 3
               Range(\"A2\").Interior.Color = 12345
               Range(\"A3\").Interior.Color = 8421504
               Range(\"B1\").Interior.ColorIndex = 5
               Range(\"B1\").Interior.ColorIndex = xlNone
               Range(\"C1\").Font.ColorIndex = 3
               Range(\"D1:D2\").Interior.ColorIndex = 3
               Named = Range(\"A1\").Interior.Color & \"|\" & _
                 Range(\"A1\").Interior.ColorIndex & \"|\" & _
                 Range(\"A2\").Interior.ColorIndex & \"|\" & _
                 Range(\"A3\").Interior.ColorIndex & \"|\" & _
                 Range(\"B1\").Interior.ColorIndex & \"|\" & _
                 Range(\"Z9\").Interior.ColorIndex & \"|\" & _
                 Range(\"C1\").Font.Color & \"|\" & _
                 Range(\"C1\").Font.ColorIndex & \"|\" & _
                 Range(\"Z9\").Font.ColorIndex & \"|\" & _
                 TypeName(Range(\"A1:A2\").Interior.ColorIndex) & \"|\" & _
                 Range(\"D1:D2\").Interior.ColorIndex
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Named", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("255|3|52|16|-4142|-4142|255|3|1|Null|3".to_string())
        );
    }

    /// What Copy sets aside can be put down again; what Cut sets aside is
    /// moved, once.
    ///
    /// Asked of Excel: `CutCopyMode` answers 0 at rest, `xlCopy` (1) after a
    /// Copy and `xlCut` (2) after a Cut; `Paste` with no destination lands on the
    /// selection; a Copy survives being pasted while a Cut does not; and
    /// pasting with nothing held raises.
    #[test]
    fn vba_puts_down_what_copy_and_cut_set_aside() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Held() As String
               Range(\"A1\").Value = 1
               Range(\"A2\").Value = 2
               Range(\"B1\").Formula = \"=A1*10\"
               Held = Application.CutCopyMode & \"|\"
               Range(\"A1:B2\").Copy
               Held = Held & Application.CutCopyMode & \"|\"
               ActiveSheet.Paste Range(\"D1\")
               Held = Held & Range(\"D1\").Value & Range(\"E1\").Formula & \"|\" & _
                 Application.CutCopyMode & \"|\"
               Range(\"G5\").Select
               ActiveSheet.Paste
               Held = Held & Range(\"G5\").Value & Range(\"H5\").Formula & \"|\"
               Range(\"A1:B2\").Cut
               Held = Held & Application.CutCopyMode & \"|\"
               ActiveSheet.Paste Range(\"J1\")
               Held = Held & Range(\"J1\").Value & Range(\"K1\").Formula & \"|\" & _
                 Application.CutCopyMode & \"|\" & \"[\" & Range(\"A1\").Value & \"]\"
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Held", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("0|1|1=D1*10|1|1=G5*10|2|1=J1*10|0|[]".to_string())
        );
    }

    /// Putting down what nothing set aside raises, and letting go empties the
    /// hand.
    #[test]
    fn vba_refuses_a_paste_with_nothing_held() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Nothing1()\n  ActiveSheet.Paste Range(\"A1\")\nEnd Sub\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let error = execute_with_host(&module, "Nothing1", vec![], &mut host)
            .expect_err("there is nothing to put down")
            .to_string();
        assert!(error.contains("nothing to put down"), "{error}");
        drop(host);

        let module = parse_module(
            "Public Function LetGo() As String
               Range(\"A1\").Value = 1
               Range(\"A1\").Copy
               Application.CutCopyMode = False
               LetGo = Application.CutCopyMode
             End Function\n",
        )
        .unwrap();
        let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
        let result = execute_with_host(&module, "LetGo", vec![], &mut host).unwrap();
        assert_eq!(result, Value::String("0".to_string()));
    }

    /// A paste can skip the blanks it carries, and can combine rather than
    /// replace.
    ///
    /// Every answer was asked of Excel: with `SkipBlanks` the cell under a
    /// blank keeps what it had; an operation makes the DESTINATION the left
    /// side and what is being put down the right, so 100 with 10 added answers
    /// 110 and `=A5+1` with 3 subtracted answers `=(A5+1)-3`; a blank counts
    /// as nothing, so multiplying by one answers 0; and text on either side
    /// leaves the cell exactly as it was.
    #[test]
    fn vba_pastes_over_blanks_or_combines_with_what_is_there() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Combined() As String
               Range(\"A1\").Value = 10
               Range(\"A3\").Value = 30
               Range(\"D1\").Value = \"keep\"
               Range(\"D2\").Value = \"keep too\"
               Range(\"D3\").Value = \"and this\"
               Range(\"F1\").Value = \"keep\"
               Range(\"F2\").Value = \"keep too\"
               Range(\"F3\").Value = \"and this\"
               Range(\"A1:A3\").Copy
               Range(\"D1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationNone, False
               Range(\"A1:A3\").Copy
               Range(\"F1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationNone, True
               Range(\"H1\").Value = 100
               Range(\"A1\").Copy
               Range(\"H1\").PasteSpecial xlPasteAll, xlPasteSpecialOperationAdd
               Range(\"H2\").Value = 100
               Range(\"A1\").Copy
               Range(\"H2\").PasteSpecial xlPasteAll, xlPasteSpecialOperationDivide
               Range(\"H3\").Formula = \"=A5+1\"
               Range(\"A5\").Value = 7
               Range(\"B1\").Value = 3
               Range(\"B1\").Copy
               Range(\"H3\").PasteSpecial xlPasteAll, xlPasteSpecialOperationSubtract
               Range(\"H4\").Value = 100
               Range(\"B2\").Value = \"abc\"
               Range(\"B2\").Copy
               Range(\"H4\").PasteSpecial xlPasteAll, xlPasteSpecialOperationMultiply
               Range(\"H5\").Value = 100
               Range(\"B3\").Copy
               Range(\"H5\").PasteSpecial xlPasteAll, xlPasteSpecialOperationMultiply
               Combined = Range(\"D2\").Value & \"|\" & Range(\"F2\").Value & \"|\" & _
                 Range(\"H1\").Value & \"|\" & Range(\"H2\").Value & \"|\" & _
                 Range(\"H3\").Formula & \"|\" & Range(\"H4\").Value & \"|\" & _
                 Range(\"H5\").Value
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Combined", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("|keep too|110|10|=(A5+1)-3|100|0".to_string())
        );
    }

    /// A transposed paste turns the formulas it carries as well as the cells.
    ///
    /// Asked of Excel with `H1:I2` — two numbers and two formulas each looking
    /// one cell to their left — pasted transposed onto K5: the block comes out
