    /// The ranking family, on a block holding things that are not numbers.
    ///
    /// Every answer was asked of Excel about 10, 30, 20, "text", a blank, TRUE
    /// and 30: only the numbers are read, so `Large` runs 30, 30, 20, 10 and
    /// then refuses; equal numbers share a place and the next one is skipped,
    /// so 20 ranks third; `CountBlank` counts the one cell that is really
    /// blank; and the plain spread is the SAMPLE one, dividing by one less
    /// than the count.
    #[test]
    fn vba_ranks_and_spreads_the_numbers_in_a_block() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ranked() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = 30
               Range(\"A3\").Value = 20
               Range(\"A4\").Value = \"text\"
               Range(\"A6\").Value = True
               Range(\"A7\").Value = 30
               Ranked = WorksheetFunction.Large(Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Large(Range(\"A1:A7\"), 3) & \"|\" & _
                 WorksheetFunction.Large(Range(\"A1:A7\"), 1.7) & \"|\" & _
                 WorksheetFunction.Small(Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Small(Range(\"A1:A7\"), 4) & \"|\" & _
                 WorksheetFunction.CountBlank(Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(30, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(20, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(10, Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Rank(30, Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Rank(10, Range(\"A1:A7\"), 1) & \"|\" & _
                 WorksheetFunction.Round(WorksheetFunction.Var(Range(\"A1:A7\")), 4) & \"|\" & _
                 WorksheetFunction.Var_P(Range(\"A1:A7\")) & \"|\" & _
                 WorksheetFunction.Large(Array(5, 15, 25), 2)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ranked", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "30|20|30|10|30|1|1|3|4|3|1|91.6667|68.75|15".to_string()
            )
        );
    }

    /// What the ranking family refuses, as Excel refuses it.
    #[test]
    fn vba_refuses_a_place_that_is_not_there() {
        for call in [
            "WorksheetFunction.Large(Range(\"A1:A3\"), 4)",
            "WorksheetFunction.Large(Range(\"A1:A3\"), 0)",
            "WorksheetFunction.Small(Range(\"A1:A3\"), 9)",
            "WorksheetFunction.Rank(25, Range(\"A1:A3\"))",
            "WorksheetFunction.StDev(Range(\"A1:A1\"))",
        ] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Ask()
                   Range(\"A1\").Value = 10
                   Range(\"A2\").Value = 30
                   Range(\"A3\").Value = 20
                   Debug.Print {call}
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            assert!(
                execute_with_host(&module, "Ask", vec![], &mut host).is_err(),
                "{call} should have refused"
            );
        }
    }

    /// Several blocks named as one range.
    ///
    /// Every answer was asked of Excel: `Union(A1:A2, C1:C2)` says its address
    /// with a comma between the blocks, counts 4 cells over 2 areas, and
    /// answers for the FIRST block where it has to give one answer — `.Row` 1,
    /// `.Rows.Count` 2. Blocks that JOIN are one block, whether they overlap
    /// (A1:A3 with A2:A4) or merely touch (A1:A2 with A3:A4): both answer
    /// `A1:A4` with one area.
    #[test]
    fn vba_names_several_blocks_as_one_range() {
        // The last arm is the one that separates the two rules: `Union` joins
        // blocks that touch, and a comma-written address never joins anything.
        // Measured in Excel 16.0 — `Union(A1:A2, A3:A4)` is `A1:A4` with one
        // area, `Range("A1:A2,A3:A4")` is `A1:A2,A3:A4` with two.

        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Joined() As String
               Dim broken
               Set broken = Application.Union(Range(\"A1:A2\"), Range(\"C1:C2\"))
               Joined = broken.Address(False, False) & \"|\" & _
                 broken.Areas.Count & \"|\" & broken.Count & \"|\" & _
                 broken.Areas(2).Address(False, False) & \"|\" & _
                 broken.Row & \"|\" & broken.Column & \"|\" & _
                 broken.Rows.Count & \"|\" & broken.Columns.Count & \"|\" & _
                 Application.Union(Range(\"A1:A3\"), Range(\"A2:A4\")).Address(False, False) & \"|\" & _
                 Application.Union(Range(\"A1:A2\"), Range(\"A3:A4\")).Address(False, False) & \"|\" & _
                 Range(\"A1:A2,C1:C2\").Areas.Count & \"|\" & _
                 Range(\"A1:A2,A3:A4\").Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Joined", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                "A1:A2,C1:C2|2|4|C1:C2|1|1|2|1|A1:A4|A1:A4|2|A1:A2,A3:A4".to_string()
            )
        );
    }

    /// What is done to a many-block range is done to every block of it.
    ///
    /// Asked of Excel, colouring `Union(A1:A2, C1:C2)` leaves A1 and C2 red
    /// and B1 — which is between them and in neither block — as it was, and
    /// writing 7 to it writes 7 to both blocks.
    #[test]
    fn vba_dresses_every_block_of_a_many_block_range() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Dressed() As String
               Dim broken
               Set broken = Application.Union(Range(\"A1:A2\"), Range(\"C1:C2\"))
               broken.Interior.Color = 255
               broken.Font.Bold = True
               broken.Value = 7
               Dressed = Range(\"A1\").Interior.Color & \"|\" & _
                 Range(\"C2\").Interior.Color & \"|\" & _
                 Range(\"B1\").Interior.Color & \"|\" & _
                 Range(\"C1\").Font.Bold & \"|\" & _
                 Range(\"A1\").Value & \"|\" & Range(\"C2\").Value & \"|\" & _
                 \"[\" & Range(\"B2\").Value & \"]\"
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Dressed", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("255|255|16777215|True|7|7|[]".to_string())
        );
    }

    /// The cells of a block that answer to a description.
    ///
    /// Every answer was asked of Excel about A1:A8 holding 10, "text", a
    /// blank, `=A1*2`, 30, `=1/0`, a blank and TRUE.
    #[test]
    fn vba_picks_out_the_cells_that_answer_a_description() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Picked() As String
               Range(\"A1\").Value = 10
               Range(\"A2\").Value = \"text\"
               Range(\"A4\").Formula = \"=A1*2\"
               Range(\"A5\").Value = 30
               Range(\"A6\").Value = True
               Range(\"C3\").Value = \"corner\"
               Picked = Range(\"A1:A8\").SpecialCells(xlCellTypeConstants).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlNumbers).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlTextValues).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, 3).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeConstants, xlLogical).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeFormulas).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeBlanks).Address(False, False) & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeBlanks).Areas.Count & \"|\" & _
                 Range(\"A1:A8\").SpecialCells(xlCellTypeVisible).Address(False, False) & \"|\" & _
                 Range(\"A1\").SpecialCells(xlCellTypeLastCell).Address(False, False)
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Picked", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String(
                // Blanks are looked for inside the used range only (A1:C6):
                // measured, Excel answers A3 and one area, not A3,A7:A8.
                "A1:A2,A5:A6|A1,A5|A2|A1:A2,A5|A6|A4|A3|1|A1:A8|C6".to_string()
            )
        );
    }

    /// After a filter, the visible cells are the rows the filter left showing.
