    /// Each kind of paste carries a different part of what was copied.
    ///
    /// Measured on Excel with a source holding a formula, a red fill, a number
    /// format and a line under it, put down on a cell that was green with its
    /// own format: `xlPasteAllExceptBorders` carried everything but the line,
    /// `xlPasteColumnWidths` carried nothing but the width of the column, and
    /// `xlPasteValuesAndNumberFormats` carried the VALUE 遯�E�繝ｻnot the formula 遯�E�繝ｻ    /// and the number format, leaving the fill alone.
    #[test]
    fn vba_pastes_the_part_of_a_cell_that_was_asked_for() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Parts() As String
               Range(\"A1\").Value = 5
               Range(\"B1\").Formula = \"=A1*2\"
               Range(\"B1\").Interior.Color = 255
               Range(\"B1\").NumberFormat = \"0.00\"
               Range(\"B1\").Borders(xlEdgeBottom).LineStyle = xlContinuous
               Range(\"B1\").ColumnWidth = 25
               Range(\"H1\").Value = 99
               Range(\"H1\").Interior.Color = 65280
               Range(\"H1\").NumberFormat = \"0%\"
               Range(\"B1\").Copy
               Range(\"H1\").PasteSpecial xlPasteAllExceptBorders
               Range(\"I1\").Value = 99
               Range(\"B1\").Copy
               Range(\"I1\").PasteSpecial xlPasteColumnWidths
               Range(\"J1\").Value = 99
               Range(\"J1\").Interior.Color = 65280
               Range(\"K1\").Value = 5
               Range(\"K1\").NumberFormat = \"0.00\"
               Range(\"K1\").Interior.Color = 255
               Range(\"K1\").Copy
               Range(\"J1\").PasteSpecial xlPasteValuesAndNumberFormats
               Parts = Range(\"H1\").Formula & \"|\" & Range(\"H1\").Interior.Color & \"|\" & _
                 Range(\"H1\").NumberFormat & \"|\" & Range(\"H1\").Borders(xlEdgeBottom).LineStyle & \"|\" & _
                 Range(\"I1\").Value & \"|\" & Range(\"I1\").ColumnWidth & \"|\" & _
                 Range(\"J1\").Formula & \"|\" & Range(\"J1\").NumberFormat & \"|\" & _
                 Range(\"J1\").Interior.Color
             End Function\n",
        )
        .unwrap();
        let result = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Parts", vec![], &mut host).unwrap()
        };

        assert_eq!(
            result,
            Value::String("=G1*2|255|0.00|-4142|99|25|5|0.00|65280".to_string())
        );
    }


    #[test]
    fn udf_scalar_and_reference_arguments_match_native_excel() {
        let fixture: serde_json::Value = serde_json::from_str(include_str!("../../../tests/fixtures/vba/udf_scalar_host.json")).unwrap();
        let mut count = 0;
        for group in fixture["groups"].as_array().unwrap() {
            let (source, packet): (&str, &[u8]) = match group["source"].as_str().unwrap() {
                "udf_reference_readiness.bas"=>(include_str!("../../../tests/fixtures/vba/udf_reference_readiness.bas"),include_bytes!("../../../tests/fixtures/vba/udf_reference_readiness.xlsm")),
                "udf_scalar_shapes.bas"=>(include_str!("../../../tests/fixtures/vba/udf_scalar_shapes.bas"),include_bytes!("../../../tests/fixtures/vba/udf_scalar_shapes.xlsm")),
                "udf_array_shapes.bas"=>(include_str!("../../../tests/fixtures/vba/udf_array_shapes.bas"),include_bytes!("../../../tests/fixtures/vba/udf_array_shapes.xlsm")),
                "udf_metadata_dependencies.bas"=>(include_str!("../../../tests/fixtures/vba/udf_metadata_dependencies.bas"),include_bytes!("../../../tests/fixtures/vba/udf_metadata_dependencies.xlsm")),
                "udf_builtin_precedents.bas"=>(include_str!("../../../tests/fixtures/vba/udf_builtin_precedents.bas"),include_bytes!("../../../tests/fixtures/vba/udf_builtin_precedents.xlsm")),
                "udf_metadata_extended.bas"=>(include_str!("../../../tests/fixtures/vba/udf_metadata_extended.bas"),include_bytes!("../../../tests/fixtures/vba/udf_metadata_extended.xlsm")),
                "udf_metadata_volatility.bas"=>(include_str!("../../../tests/fixtures/vba/udf_metadata_volatility.bas"),include_bytes!("../../../tests/fixtures/vba/udf_metadata_volatility.xlsm")),
                "implicit_error_coercion.bas"=>(include_str!("../../../tests/fixtures/vba/implicit_error_coercion.bas"),include_bytes!("../../../tests/fixtures/vba/implicit_error_coercion.xlsm")),
                "metadata_argument_errors.bas"=>(include_str!("../../../tests/fixtures/vba/metadata_argument_errors.bas"),include_bytes!("../../../tests/fixtures/vba/metadata_argument_errors.xlsm")),
                "reference_producers.bas"=>(include_str!("../../../tests/fixtures/vba/reference_producers.bas"),include_bytes!("../../../tests/fixtures/vba/reference_producers.xlsm")),
                "reference_scopes.bas" => (include_str!("../../../tests/fixtures/vba/reference_scopes.bas"), include_bytes!("../../../tests/fixtures/vba/reference_scopes.xlsm")),
                "udf_evaluate_shapes.bas" => (include_str!("../../../tests/fixtures/vba/udf_evaluate_shapes.bas"), include_bytes!("../../../tests/fixtures/vba/udf_evaluate_shapes.xlsm")),
                "udf_cell_shape_contexts.bas" => (include_str!("../../../tests/fixtures/vba/udf_cell_shape_contexts.bas"), include_bytes!("../../../tests/fixtures/vba/udf_cell_shape_contexts.xlsm")),
                _ => panic!("unknown Native argument group"),
            };
            for case in group["cases"].as_array().unwrap() {
                let book = oxicells_core::parse_xlsx(packet).unwrap();
                let mut session = None;
                let step = &case["steps"][0];
                let args = step["arguments"].as_array().unwrap().iter().map(|v| Value::Integer(v.as_i64().unwrap())).collect();
                let outcome = execute_workbook_action_in_session(book, source, step["procedure"].as_str(), args, 0, failure_context(), &mut session).unwrap();
                assert!(outcome.error.is_none(), "Native argument {}: {:?}", case["id"], outcome.error.as_ref().map(|e| &e.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":step["expected"]}), "Native argument {}", case["id"]);
                count += 1;
            }
        }
        assert_eq!(count, 518);
    }

