        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), range_source, Some("MakeCut"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=C1|=C2|=C3"}));
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
