    #[test]
    fn paste_special_validation_matches_excel_after_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        for (source_rule, paste, expected) in [
            (true, "PasteSpecial 6", "=F1+$E$2|=I1|=J1|=F2+$E$2|=F3+$E$2|123"),
            (true, "PasteSpecial 6,-4142,True,False", "=F1+$E$2|=I1|=J1|=F2+$E$2|=F3+$E$2|123"),
            (true, "PasteSpecial 6,-4142,False,True", "=F1+$E$2|=G1+$E$2|=H1+$E$2|=H2|=H3|123"),
            (true, "PasteSpecial -4104", "=F1+$E$2|=I1|=J1|=F2+$E$2|=F3+$E$2|"),
            (true, "PasteSpecial 7,-4142,True,False", "=F1+$E$2|=I1|=J1|=F2+$E$2|=F3+$E$2|123"),
            (true, "PasteSpecial -4123", "=H1|=I1|=J1|=H2|=H3|"),
            (true, "PasteSpecial -4122", "=H1|=I1|=J1|=H2|=H3|123"),
            (false, "PasteSpecial 6", "none|=I1|=J1|none|none|123"),
            (false, "PasteSpecial 6,-4142,True,False", "=H1|=I1|=J1|=H2|=H3|123"),
            (false, "PasteSpecial -4104,-4142,True,False", "=H1|=I1|=J1|=H2|=H3|123"),
        ] {
            let setup = if source_rule { "Range(\"A1:A3\").Validation.Add 7,1,1,\"=D1+$E$2\"" } else { "" };
            let source = format!("Public Function MakePaste() As String\nWorksheets.Add\n{setup}\nRange(\"C1:E3\").Validation.Add 7,1,1,\"=H1\"\nRange(\"C1\").Value=123\nRange(\"A1:A3\").Copy\nRange(\"C1\").{paste}\nMakePaste=ReadPaste()\nEnd Function\nPublic Function ReadPaste() As String\nReadPaste=OneRule(\"C1\") & \"|\" & OneRule(\"D1\") & \"|\" & OneRule(\"E1\") & \"|\" & OneRule(\"C2\") & \"|\" & OneRule(\"C3\") & \"|\" & CStr(Range(\"C1\").Value)\nEnd Function\nPublic Function OneRule(ByVal address As String) As String\nOn Error Resume Next\nOneRule=Range(address).Validation.Formula1\nIf Err.Number<>0 Then Err.Clear: OneRule=\"none\"\nEnd Function");
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("MakePaste"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{paste}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "runtime {paste}");
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadPaste"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "reopened {paste}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened {paste}");
        }
    }

    #[test]
    fn copied_validation_tracks_relative_references_and_survives_save() {
        let bytes = include_bytes!("../../../tests/fixtures/vba/row_height_state.xlsm");
        for (operation, expected) in [
            ("Range(\"A1:A3\").Validation.Add 7,1,1,\"=D1+$E$2\": Range(\"A1:A3\").Copy Range(\"C1\")", "=F1+$E$2|=F2+$E$2|=F3+$E$2"),
            ("Range(\"C1:C3\").Validation.Add 7,1,1,\"=H1\": Range(\"A1:A3\").Copy Range(\"C1\")", "none|none|none"),
            ("Range(\"A1:A3\").Validation.Add 7,1,1,\"=A1+$A$2\": Range(\"A1:A3\").Copy Range(\"C1\")", "=C1+$A$2|=C2+$A$2|=C3+$A$2"),
        ] {
            let source = format!("Public Function MakeCopy() As String\nWorksheets.Add\n{operation}\nMakeCopy=ReadCopy()\nEnd Function\nPublic Function ReadCopy() As String\nReadCopy=OneRule(\"C1\") & \"|\" & OneRule(\"C2\") & \"|\" & OneRule(\"C3\")\nEnd Function\nPublic Function OneRule(ByVal address As String) As String\nOn Error Resume Next\nOneRule=Range(address).Validation.Formula1\nIf Err.Number<>0 Then Err.Clear: OneRule=\"none\"\nEnd Function");
            let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), &source, Some("MakeCopy"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "{operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "runtime {operation}");
            let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
            editor.apply_workbook(&result.workbook).unwrap();
            let reopened = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
            let result = execute_workbook_action_in_session(reopened, &source, Some("ReadCopy"), vec![], 0, failure_context(), &mut None).unwrap();
            assert!(result.error.is_none(), "reopened {operation}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "reopened {operation}");
        }
        let source = "Public Sub MakeRule()\nWorksheets.Add\nRange(\"A1:A3\").Validation.Add 7,1,1,\"=D1+$E$2\"\nEnd Sub\nPublic Function CopyLoaded() As String\nRange(\"A1:A3\").Copy Range(\"C1\")\nCopyLoaded=Range(\"C1\").Validation.Formula1 & \"|\" & Range(\"C3\").Validation.Formula1\nEnd Function";
        let result = execute_workbook_action_in_session(oxicells_core::parse_xlsx(bytes).unwrap(), source, Some("MakeRule"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        let mut editor = oxicells_core::XlsxEditor::new(bytes).unwrap();
        editor.apply_workbook(&result.workbook).unwrap();
        let loaded = oxicells_core::parse_xlsx(&editor.save().unwrap()).unwrap();
        let result = execute_workbook_action_in_session(loaded, source, Some("CopyLoaded"), vec![], 0, failure_context(), &mut None).unwrap();
        assert!(result.error.is_none());
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"=F1+$E$2|=F3+$E$2"}));
    }

