    #[test]
    fn column_shift_preserves_column_widths_like_excel() {
        // Excel 16.0 build 20527: entire-column shifts carry width and
        // visibility; cell-only shifts leave the column properties alone.
        let source = r#"Public Function ColumnShiftWidth(ByVal mode As Long) As String
Columns(1).ColumnWidth = 12: Columns(2).ColumnWidth = 20: Columns(3).ColumnWidth = 30
Range("B1").Value2 = 11: Range("C1").Value2 = 22
If mode = 0 Then Columns(2).Insert
If mode = 1 Then Columns(2).Delete
If mode = 2 Then Range("B1").Insert xlShiftToRight
If mode = 3 Then Range("B1").Delete xlShiftToLeft
If mode = 4 Then Columns(1).Insert
If mode = 5 Then Columns(1).Hidden = True: Columns(2).Insert
If mode = 6 Then Columns(3).Hidden = True: Columns(2).Delete
If mode = 7 Then Range("B:C").EntireColumn.Insert
If mode = 8 Then Columns(2).Insert xlShiftToRight, 1
If mode = 9 Then Columns(2).Hidden = True: Columns(2).Insert xlShiftToRight, 1
ColumnShiftWidth = CStr(Columns(1).ColumnWidth) & "|" & CStr(Columns(2).ColumnWidth) & "|" & CStr(Columns(3).ColumnWidth) & "|" & CStr(Columns(4).ColumnWidth)
End Function"#;
        for (mode, expected) in [(0, "12|12|20|30"), (1, "12|30|8.43|8.43"), (2, "12|20|30|8.43"), (3, "12|20|30|8.43"), (4, "8.43|12|20|30"), (5, "0|12|20|30"), (6, "12|0|8.43|8.43"), (7, "12|12|12|20"), (8, "12|20|20|30"), (9, "12|20|0|30")] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, source, Some("ColumnShiftWidth"), vec![Value::Integer(mode)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "mode={mode}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "mode={mode}");
        }
    }

    #[test]
    fn row_shift_preserves_row_heights_like_excel() {
        // Excel 16.0 build 20527: whole rows carry their height; partial
        // cell shifts leave row heights in place, including empty rows.
        let source = r#"Public Function RowShiftHeight(ByVal mode As Long) As String
Rows(1).RowHeight = 25: Rows(2).RowHeight = 33: Rows(3).RowHeight = 45
Range("A2").Value2 = 11: Range("A3").Value2 = 22
If mode = 0 Then Rows(2).Insert
If mode = 1 Then Rows(2).Delete
If mode = 2 Then Range("A2").Insert xlShiftDown
If mode = 3 Then Range("A2").Delete xlShiftUp
If mode = 4 Then Rows(1).Insert
If mode = 5 Then Rows(1).Hidden = True: Rows(2).Insert
If mode = 6 Then Range("A2:A3").ClearContents: Range("A2").Insert xlShiftDown
If mode = 7 Then Rows(2).Insert xlShiftDown, 1
If mode = 8 Then Rows(2).Hidden = True: Rows(2).Insert xlShiftDown, 1
RowShiftHeight = CStr(Rows(1).RowHeight) & "|" & CStr(Rows(2).RowHeight) & "|" & CStr(Rows(3).RowHeight) & "|" & CStr(Rows(4).RowHeight)
End Function"#;
        for (mode, expected) in [(0, "25|25|33|45"), (1, "25|45|15|15"), (2, "25|33|45|15"), (3, "25|33|45|15"), (4, "15|25|33|45"), (5, "0|25|33|45"), (6, "25|33|45|15"), (7, "25|33|33|45"), (8, "25|33|0|45")] {
            let mut book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            book.sheets[0].default_row_height = 15.0;
            let mut session = None;
            let result = execute_workbook_action_in_session(book, source, Some("RowShiftHeight"), vec![Value::Integer(mode)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "mode={mode}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "mode={mode}");
        }
    }

    #[test]
    fn structural_shift_marks_workbook_unsaved_like_excel() {
        let source = r#"Option Explicit
Public Function VolSavedProbe(ByVal axis As Long) As String
Dim previous As Long
previous = Application.Calculation: Application.Calculation = xlCalculationManual
ThisWorkbook.Saved = True
If axis = 0 Then
Rows(1).Insert
Else
Columns(1).Insert
End If
VolSavedProbe = CStr(ThisWorkbook.Saved)
If axis = 0 Then
Rows(1).Delete
Else
Columns(1).Delete
End If
Application.Calculation = previous
End Function
"#;
        // Excel20527, three fresh processes per axis and operation.
        for deleting in [false, true] {
          let source = if deleting {
              source.replace("Rows(1).Insert", "__ROW_DEL__")
                  .replace("Rows(1).Delete", "Rows(1).Insert")
                  .replace("__ROW_DEL__", "Rows(1).Delete")
                  .replace("Columns(1).Insert", "__COL_DEL__")
                  .replace("Columns(1).Delete", "Columns(1).Insert")
                  .replace("__COL_DEL__", "Columns(1).Delete")
          } else { source.to_string() };
          for axis in [0, 1] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("VolSavedProbe"), vec![Value::Integer(axis)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "deleting={deleting} axis={axis}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":"False"}), "deleting={deleting} axis={axis}");
          }
        }
    }

    #[test]
    fn multiple_functions_volatility_order_matches_recorded_excel() {
        let mut source = returned_reference_trace_source();
        source.push_str(r#"
Public Function VolA() As Long
    Application.Volatile True
    hitsA = hitsA + 1
    trace = trace & traceStage & ":A|"
    VolA = 10
End Function
Public Function VolB() As Long
    Application.Volatile False
    hitsB = hitsB + 1
    trace = trace & traceStage & ":B|"
    VolB = 20
End Function
Private Function VolSnap(ByVal stage As String) As String
    VolSnap = stage & ":" & CStr(hitsA) & "," & CStr(hitsB) & "," & CStr(Range("Z1").Value2)
End Function
Public Function VolProbe(ByVal kind As Long) As String
    Dim previous As Long, report As String, expression As String
    previous = Application.Calculation
    Application.Calculation = xlCalculationManual
    Range("Z1").ClearContents
    hitsA = 0: hitsB = 0: trace = "": traceStage = "seed"
    If kind = 0 Then expression = "=VolA()+VolB()" Else expression = "=VolB()+VolA()"
    Range("Z1").Formula2 = expression
    Application.CalculateFull
    report = VolSnap("seed")
    traceStage = "clean": Application.Calculate
    report = report & "|" & VolSnap("clean")
    traceStage = "dirty": Range("D9").Value2 = 1: Application.Calculate
    report = report & "|" & VolSnap("dirty")
    traceStage = "again": Application.Calculate
    report = report & "|" & VolSnap("again")
    traceStage = "full": Application.CalculateFull
    VolProbe = report & "|" & VolSnap("full")
    Range("Z1").ClearContents
    Application.Calculation = previous
End Function
"#);
        // Excel 20527: three fresh processes per order, including clean and
        // dirty Calculate calls, followed by CalculateFull.
        for (kind, expected, expected_trace) in [
            (0, "seed:2,2,30|clean:2,2,30|dirty:2,2,30|again:2,2,30|full:3,3,30", "seed:A|seed:B|seed:A|seed:B|full:A|full:B|"),
            (1, "seed:2,2,30|clean:3,3,30|dirty:4,4,30|again:5,5,30|full:6,6,30", "seed:B|seed:A|seed:B|seed:A|clean:B|clean:A|dirty:B|dirty:A|again:B|again:A|full:B|full:A|"),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("VolProbe"), vec![Value::Integer(kind)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none(), "kind={kind}");
            assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "kind={kind}");
            let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            assert_eq!(serde_json::to_value(&trace.result).unwrap(), serde_json::json!({"type":"string", "value":expected_trace}), "kind={kind}");
        }
    }

    #[test]
    fn multiple_returned_references_full_matches_observed_excel() {
        let source = returned_reference_trace_source();
        let formula = "Case 3: expression = \"=FlowTick(\"\"B\"\",RefRange())\"";
        assert!(source.contains(formula));
        let source = source.replacen(formula, "Case 3: expression = \"=FlowTick(\"\"B\"\",RefRange())+RefOther()\"", 1);
        let marker = "Private Function FlowSnapshot";
        assert!(source.contains(marker));
        let source = source.replacen(marker, "Public Function RefOther() As Range\n    hitsR = hitsR + 1\n    trace = trace & traceStage & \":S|\"\n    Set RefOther = Range(\"O1\")\nEnd Function\n\nPrivate Function FlowSnapshot", 1);
        // Each sequence occurred twice in independent Excel 20527 processes.
        // Excel also produced another order; these checks cover these samples.
        for (initial, full_result, events) in [
            (0, "full:4,8,4,7[5:1,5:14,5:14,5:13]", vec!["full:C=13", "full:A=1", "full:R", "full:B=1", "full:S", "full:B=14"]),
            (1, "full:4,8,4,7[5:0,5:13,5:13,5:13]", vec!["full:C=13", "full:A=0", "full:R", "full:B=0", "full:S", "full:B=13"]),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("FlowCase"), vec![Value::Integer(3), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none());
            let value = serde_json::to_value(&result.result).unwrap();
            assert!(value["value"].as_str().unwrap().ends_with(full_result), "initial={initial}");
            let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let value = serde_json::to_value(&trace.result).unwrap();
            let actual: Vec<_> = value["value"].as_str().unwrap().split('|').filter(|event| event.starts_with("full:")).collect();
            assert_eq!(actual, events, "initial={initial}");
        }
    }

