    #[test]
    fn returned_reference_full_then_dirty_matches_current_native_excel() {
        let source = returned_reference_trace_source();
        let anchor = "    FlowCase = report & \"|\" & FlowSnapshot(\"full\")";
        assert!(source.contains(anchor));
        let mut source = source.replacen(anchor, &format!("{anchor}\n    Exit Function"), 1);
        source.push_str("\nPublic Function AfterDirty() As String\ntraceStage = \"after\"\nRange(\"D1\").Value2 = 1 - Range(\"D1\").Value2\nApplication.Calculate\nAfterDirty = FlowSnapshot(\"after\")\nEnd Function\n");
        // Excel build 20527: each Full trace occurred at least once;
        // the following dirty result occurred in both observed processes.
        for (kind, initial, expected, event, full_result, full_events) in [
            (3, 0, "after:5,8,4,4[5:0,5:1,5:1,5:13]", "after:A=0", "full:4,8,4,4[5:1,5:1,5:1,5:13]", vec!["full:C=13", "full:A=1", "full:R", "full:B=1", "full:B=1"]),
            (3, 1, "after:5,8,4,4[5:1,5:0,5:0,5:13]", "after:A=1", "full:4,8,4,4[5:0,5:0,5:0,5:13]", vec!["full:C=13", "full:A=0", "full:R", "full:B=0", "full:B=0"]),
            (1, 1, "after:5,4,4,4[5:1,5:0,5:0,5:13]", "after:A=1", "full:4,4,4,4[5:0,5:0,5:0,5:13]", vec!["full:C=13", "full:A=0", "full:R", "full:B=0"]),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let full = execute_workbook_action_in_session(book, &source, Some("FlowCase"), vec![Value::Integer(kind), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(full.error.is_none());
            let full_json = serde_json::to_value(&full.result).unwrap();
            assert!(full_json["value"].as_str().unwrap().ends_with(full_result), "kind={kind} initial={initial}");
            let trace = execute_workbook_action_in_session(full.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let full_trace = serde_json::to_value(&trace.result).unwrap();
            let actual_full: Vec<_> = full_trace["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("full:")).collect();
            assert_eq!(actual_full, full_events, "kind={kind} initial={initial}");
            let after = execute_workbook_action_in_session(trace.workbook, &source, Some("AfterDirty"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(after.error.is_none());
            assert_eq!(serde_json::to_value(&after.result).unwrap(), serde_json::json!({"type":"string", "value":expected}), "kind={kind} initial={initial}");
            let trace = execute_workbook_action_in_session(after.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let trace = serde_json::to_value(&trace.result).unwrap();
            let events: Vec<_> = trace["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("after:")).collect();
            assert_eq!(events, vec![event], "kind={kind} initial={initial}");
        }
    }

    #[test]
    fn direct_returned_reference_full_calculation_matches_native_trace() {
        // Excel 16.0 build 20430, Japanese UI: one recorded trace of this
        // instrumented source. Keep the full trace as well as the hit counts:
        // callers can observe ordering through VBA side effects.
        let source = returned_reference_trace_source();
        let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
        let mut session = None;
        let result = execute_workbook_action_in_session(book, &source, Some("FlowCase"), vec![Value::Integer(0), Value::Integer(0)], 0, failure_context(), &mut session).unwrap();
        assert!(result.error.is_none());
        let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
        assert!(trace.error.is_none());
        let expected = "entry:1,1,1,1[5:0,5:0,5:0,5:9]|normal:2,3,2,2[5:0,5:0,5:0,5:9]|again:2,3,2,2[5:0,5:0,5:0,5:9]|dirty:3,3,2,2[5:1,5:0,5:0,5:9]|switch:3,3,2,2[5:1,5:0,5:0,5:9]|other:3,3,3,2[5:1,5:0,5:0,5:13]|full:4,4,4,4[5:1,5:1,5:1,5:13]";
        let expected_trace = "entry:A=0|entry:C=9|entry:R|entry:B=0|normal:B=0|normal:A=0|normal:C=9|normal:R|normal:B=0|dirty:A=1|other:C=13|full:R|full:C=13|full:A=1|full:R|full:B=1|";
        assert_eq!(serde_json::to_value(&result.result).unwrap(), serde_json::json!({"type":"string", "value":expected}));
        assert_eq!(serde_json::to_value(&trace.result).unwrap(), serde_json::json!({"type":"string", "value":expected_trace}));
        let check_selector_full = |outcome: &RunOutcome, initial| {
            // These are prior Oxi results, not Excel observations.
            let expected = if initial == 0 {
                "|full:4,4,4,3[5:1,5:13,5:13,5:13]"
            } else {
                "|full:4,4,4,3[5:0,5:13,5:13,5:13]"
            };
            let json = serde_json::to_value(&outcome.result).unwrap();
            assert!(json["value"].as_str().unwrap().ends_with(expected), "dynamic reference full result initial={initial}: {json}");
        };
        // RefPick reads a cell to select its target. The previous target is
        // not a safe ordering hint after that cell changes. Preserve the
        // prior implementation's normal-pass order for both initial values.
        for (initial, expected_normal) in [
            (0, vec!["normal:B=0", "normal:C=9", "normal:A=0", "normal:B=0"]),
            (1, vec!["normal:B=0", "normal:C=9", "normal:A=1", "normal:B=1"]),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("FlowCase"), vec![Value::Integer(9), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none());
            check_selector_full(&result, initial);
            let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let json = serde_json::to_value(&trace.result).unwrap();
            let actual: Vec<_> = json["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("normal:")).collect();
            assert_eq!(actual, expected_normal, "dynamic reference selector initial={initial}");
        }
        let text_source = source.replace("If Range(\"D2\").Value2 = 0 Then", "If Range(\"D2\").Text = \"0\" Then");
        assert_ne!(text_source, source);
        for (initial, expected_normal) in [
            (0, vec!["normal:B=0", "normal:C=9", "normal:A=0", "normal:B=0"]),
            (1, vec!["normal:B=0", "normal:C=9", "normal:A=1", "normal:B=1"]),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &text_source, Some("FlowCase"), vec![Value::Integer(9), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none());
            check_selector_full(&result, initial);
            let trace = execute_workbook_action_in_session(result.workbook, &text_source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let json = serde_json::to_value(&trace.result).unwrap();
            let actual: Vec<_> = json["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("normal:")).collect();
            assert_eq!(actual, expected_normal, "text reference selector initial={initial}");
        }
        for member in ["Value", "Formula"] {
            let selector = format!("If Range(\"D2\").{member} = 0 Then");
            let selector_source = source.replace("If Range(\"D2\").Value2 = 0 Then", &selector);
            assert_ne!(selector_source, source);
            for (initial, expected_normal) in [
                (0, vec!["normal:B=0", "normal:C=9", "normal:A=0", "normal:B=0"]),
                (1, vec!["normal:B=0", "normal:C=9", "normal:A=1", "normal:B=1"]),
            ] {
                let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
                let mut session = None;
                let result = execute_workbook_action_in_session(book, &selector_source, Some("FlowCase"), vec![Value::Integer(9), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
                assert!(result.error.is_none());
                check_selector_full(&result, initial);
                let trace = execute_workbook_action_in_session(result.workbook, &selector_source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
                assert!(trace.error.is_none());
                let json = serde_json::to_value(&trace.result).unwrap();
                let actual: Vec<_> = json["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("normal:")).collect();
                assert_eq!(actual, expected_normal, "{member} reference selector initial={initial}");
            }
        }
        // A module variable can change a returned reference without a host
        // value read. The old implementation's order is a control, not an
        // Excel observation.
        let mut variable_source = source.clone();
        for (before, after) in [
            ("Private trace As String, traceStage As String", "Private trace As String, traceStage As String\nPrivate selectedAddress As String"),
            ("    If Range(\"D2\").Value2 = 0 Then\n        Set RefPick = Range(\"M1\")\n    Else\n        Set RefPick = Range(\"O1\")\n    End If", "    Set RefPick = Range(selectedAddress)"),
            ("    Range(\"D3\").Value2 = 9", "    Range(\"D3\").Value2 = 9\n    selectedAddress = \"M1\""),
            ("    Range(\"D2\").Value2 = 1", "    Range(\"D2\").Value2 = 1\n    selectedAddress = \"O1\""),
        ] {
            assert!(variable_source.contains(before));
            variable_source = variable_source.replacen(before, after, 1);
        }
        for (initial, expected_normal) in [
            (0, vec!["normal:B=0", "normal:C=9", "normal:A=0", "normal:B=0"]),
            (1, vec!["normal:B=0", "normal:C=9", "normal:A=1", "normal:B=1"]),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &variable_source, Some("FlowCase"), vec![Value::Integer(9), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none());
            check_selector_full(&result, initial);
            let trace = execute_workbook_action_in_session(result.workbook, &variable_source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let json = serde_json::to_value(&trace.result).unwrap();
            let actual: Vec<_> = json["value"].as_str().unwrap().split('|').filter(|item| item.starts_with("normal:")).collect();
            assert_eq!(actual, expected_normal, "variable reference selector initial={initial}");
        }
        // Excel's multithreaded calculation can interleave independent UDFs
        // differently on each run. Compare the calls within each calculation
        // stage as a multiset while retaining stage boundaries and results.
        // Excel 16.0 build 20527 produced several orders for each case, including
        // Oxi's, with independent C calls moving around the A/R/B chain.
        let calls_by_stage = |value: &str| {
            let mut stages: std::collections::BTreeMap<String, Vec<String>> = std::collections::BTreeMap::new();
            for call in value.split('|').filter(|call| !call.is_empty()) {
                let (stage, _) = call.split_once(':').expect("trace call has a stage");
                stages.entry(stage.to_string()).or_default().push(call.to_string());
            }
            for calls in stages.values_mut() { calls.sort(); }
            stages
        };
        let mut mismatches = Vec::new();
        for (kind, initial, expected, expected_trace) in [
            (3, 0, "entry:1,2,1,1[5:0,5:0,5:0,5:9]|normal:2,6,2,3[5:0,5:0,5:0,5:9]|again:2,6,2,3[5:0,5:0,5:0,5:9]|dirty:3,6,2,3[5:1,5:0,5:0,5:9]|switch:3,6,2,3[5:1,5:0,5:0,5:9]|other:3,6,3,3[5:1,5:0,5:0,5:13]|full:4,8,4,4[5:1,5:1,5:1,5:13]", "entry:A=0|entry:C=9|entry:R|entry:B=0|entry:B=0|normal:B=0|normal:R|normal:B=0|normal:C=9|normal:A=0|normal:R|normal:B=0|normal:B=0|dirty:A=1|other:C=13|full:A=1|full:R|full:B=1|full:B=1|full:C=13|"),
            (3, 1, "entry:1,2,1,1[5:1,5:1,5:1,5:9]|normal:2,6,2,3[5:1,5:1,5:1,5:9]|again:2,6,2,3[5:1,5:1,5:1,5:9]|dirty:3,6,2,3[5:0,5:1,5:1,5:9]|switch:3,6,2,3[5:0,5:1,5:1,5:9]|other:3,6,3,3[5:0,5:1,5:1,5:13]|full:4,8,4,4[5:0,5:0,5:0,5:13]", "entry:A=1|entry:C=9|entry:R|entry:B=1|entry:B=1|normal:R|normal:B=0|normal:B=0|normal:A=1|normal:C=9|normal:R|normal:B=1|normal:B=1|dirty:A=0|other:C=13|full:C=13|full:A=0|full:R|full:B=0|full:B=0|"),
            (1, 1, "entry:1,1,1,1[5:1,5:1,5:1,5:9]|normal:2,3,2,3[5:1,5:1,5:1,5:9]|again:2,3,2,3[5:1,5:1,5:1,5:9]|dirty:3,3,2,3[5:0,5:1,5:1,5:9]|switch:3,3,2,3[5:0,5:1,5:1,5:9]|other:3,3,3,3[5:0,5:1,5:1,5:13]|full:4,4,4,4[5:0,5:0,5:0,5:13]", "entry:A=1|entry:C=9|entry:R|entry:B=1|normal:R|normal:A=1|normal:B=0|normal:C=9|normal:R|normal:B=1|dirty:A=0|other:C=13|full:C=13|full:A=0|full:R|full:B=0|"),
        ] {
            let book = oxicells_core::parse_xlsx(include_bytes!("../../../tests/fixtures/vba/udf_returned_references.xlsm")).unwrap();
            let mut session = None;
            let result = execute_workbook_action_in_session(book, &source, Some("FlowCase"), vec![Value::Integer(kind), Value::Integer(initial)], 0, failure_context(), &mut session).unwrap();
            assert!(result.error.is_none());
            let trace = execute_workbook_action_in_session(result.workbook, &source, Some("CallTrace"), vec![], 0, failure_context(), &mut session).unwrap();
            assert!(trace.error.is_none());
            let result = serde_json::to_value(&result.result).unwrap();
            let trace = serde_json::to_value(&trace.result).unwrap();
            let trace_matches = trace["type"] == "string" && trace["value"].as_str().is_some_and(|value| calls_by_stage(value) == calls_by_stage(expected_trace));
            if result != serde_json::json!({"type":"string","value":expected}) || !trace_matches {
                mismatches.push(format!("kind={kind} initial={initial}: result={result}; trace={trace}"));
            }
        }
        assert!(mismatches.is_empty(), "{} native trace mismatches:\n{}", mismatches.len(), mismatches.join("\n"));
    }

    #[test]
    fn worksheet_udf_evaluation_matches_native_excel() {
        let source = include_str!("../../../tests/fixtures/vba/worksheet_udf_evaluation.bas");
        let rows: Vec<_> = include_str!("../../../tests/fixtures/vba/worksheet_udf_evaluation.tsv").lines()
            .filter(|line| !line.is_empty() && !line.starts_with('#')).map(|line| line.split('\t').collect::<Vec<_>>()).collect();
        assert_eq!(rows.len(), 434);
        for version in [1u8, 2] {
            let mut book = oxicells_core::parse_xlsx(include_bytes!("../../oxicells-core/tests/fixtures/hidden_rows_cols.xlsx")).unwrap();
            book.calculation.compatibility_version = version;
            book.calculation.dbcs_language = Some(false);
            let context = || { let mut context = failure_context(); context.host_ansi_code_page = Some(AnsiCodePage::Japanese); context };
            let mut session = None;
            let setup = execute_workbook_action_in_session(book, source, Some("Driver"), vec![], 0, context(), &mut session).unwrap();
            assert!(setup.error.is_none());
            book = serde_json::from_value(serde_json::to_value(setup.workbook).unwrap()).unwrap();
            for fields in rows.iter().filter(|fields| fields[0].parse::<u8>().unwrap() == version) {
                let args: Vec<_> = serde_json::from_str::<Vec<serde_json::Value>>(fields[2]).unwrap().into_iter().map(|value| match value {
                    serde_json::Value::Bool(value) => Value::Boolean(value),
                    serde_json::Value::Number(value) => Value::Double(value.as_f64().unwrap()),
                    serde_json::Value::String(value) => Value::String(value),
                    _ => panic!("unsupported oracle argument"),
                }).collect();
                let outcome = execute_workbook_action_in_session(book, source, Some(fields[1]), args, 0, context(), &mut session).unwrap();
                assert!(outcome.error.is_none(), "{fields:?}: {:?}", outcome.error.as_ref().map(|error| &error.message));
                assert_eq!(serde_json::to_value(&outcome.result).unwrap(), serde_json::json!({"type":"string","value":fields[3]}), "{fields:?}");
                book = serde_json::from_value(serde_json::to_value(outcome.workbook).unwrap()).unwrap();
            }
        }
    }

