    /// Thousands written out are read, and the cell is shown with them.
    ///
    /// Measured in Excel. English and Japanese separate thousands the same
    /// way, so this needs no locale behind it.
    #[test]
    fn vba_reads_a_number_whose_thousands_were_written_out() {
        let measured = [
            ("1,234", "1234", "#,##0"),
            ("12,345", "12345", "#,##0"),
            ("123,456", "123456", "#,##0"),
            ("1,234,567", "1234567", "#,##0"),
            ("-1,234", "-1234", "#,##0"),
            // A group after the first may be longer than three.
            ("1,2345", "12345", "#,##0"),
            // A point brings two decimals with it, however many were written.
            ("1,234.5", "1234.5", "#,##0.00"),
            ("1,234.56", "1234.56", "#,##0.00"),
            ("1,234.567", "1234.567", "#,##0.00"),
            // Brackets keep the separated form, where a plain (5) does not.
            ("(1,234)", "-1234", "#,##0"),
            // And a per cent stays a per cent.
            ("1,234%", "12.34", "0%"),
        ];
        for (written, value, shown) in measured {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = \"{written}\"
                   Debug.Print CStr(Range(\"A1\").Value)
                   Debug.Print Range(\"A1\").NumberFormat
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec![value.to_string(), shown.to_string()],
                "for {written}"
            );
        }
    }

    /// A group after the first that carries fewer than three digits is not a
    /// separated number at all, and neither is one with a group missing.
    #[test]
    fn vba_leaves_a_badly_separated_number_as_text() {
        for written in ["1,23", "12,34", "1,234,56", ",123", "1,"] {
            let mut workbook = workbook();
            let module = parse_module(&format!(
                "Public Sub Act()
                   Range(\"A1\").Value = \"{written}\"
                   Debug.Print TypeName(Range(\"A1\").Value)
                   Debug.Print Range(\"A1\").NumberFormat
                 End Sub\n"
            ))
            .unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            assert_eq!(
                host.take_debug_output(),
                vec!["String".to_string(), "General".to_string()],
                "for {written}"
            );
        }
    }

    /// Whole columns and rows, as ordinary macros name them. Every answer is
    /// Excel's, from the same macro run in Excel 16.
    #[test]
    fn whole_columns_are_read_searched_cleared_and_sorted() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim i As Long, n As Long, c As Range, out As String
               For i = 1 To 8
                 Cells(i, 1).Value = Choose(i, \"b\", \"a\", \"d\", \"c\", \"a\", \"e\", \"b\", \"f\")
                 Cells(i, 2).Value = i * 3
                 Cells(i, 4).Value = Choose(i, 5, 1, 9, 3, 7, 2, 8, 4)
               Next i
               With WorksheetFunction
                 out = .Match(\"d\", Range(\"A:A\"), 0) & \"|\" & .CountA(Columns(1)) & \"|\" & _
                       .CountBlank(Range(\"A:A\")) & \"|\" & .SumIf(Range(\"A:A\"), \"b\", Range(\"B:B\")) & \"|\" & _
                       .Max(Columns(\"B\")) & \"|\" & .Match(6, Range(\"D:D\"), 1) & \"|\" & _
                       .Match(6, Range(\"D1:D8\"), 1) & \"|\" & .Lookup(\"c\", Range(\"A1:A8\"), Range(\"B1:B8\")) & \"|\" & _
                       .Lookup(\"c\", Range(\"A1:A20\"), Range(\"B1:B20\")) & \"|\" & .Lookup(6, Range(\"D:D\")) & \"|\" & _
                       .HLookup(6, Range(\"1:1\"), 1, True)
               End With
               For Each c In Intersect(Range(\"A:A\"), ActiveSheet.UsedRange): n = n + 1: Next c
               out = out & \"|\" & n & \"|\" & Union(Columns(1), Columns(3)).Address & \"|\" & _
                     Range(\"B:B\").SpecialCells(xlCellTypeConstants).Address & \"|\" & _
                     Range(\"A:A\").SpecialCells(xlCellTypeVisible).Address
               Range(\"A:B\").Sort Key1:=Range(\"A1\"), Order1:=xlAscending, Header:=xlNo
               Range(\"D:D\").ClearContents
               Ask = out & \"|\" & Range(\"A1\").Value & Range(\"A8\").Value & Range(\"B1\").Value & \"|\" & _
                     IsEmpty(Range(\"D2\").Value) & \"|\" & (CVErr(xlErrDiv0) = CVErr(2007))
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "3|8|1048568|24|24|8|6|12|21|4|5|8|$A:$A,$C:$C|$B$1:$B$8|$A:$A|af6|True|True"
                    .to_string()
            )
        );
    }

    /// A formula dresses a cell still in General from what it reads. Every
    /// answer here is Excel 16's, from the same macro.
    #[test]
    fn a_formula_dresses_its_cell_from_what_it_reads() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Range(\"A1\").Value = DateSerial(2024, 1, 31)
               Range(\"A2\").Value = DateSerial(2024, 3, 1)
               Range(\"A3\").Value = 0.25: Range(\"A3\").NumberFormat = \"0%\"
               Range(\"A4\").Value = 1234.5: Range(\"A4\").NumberFormat = \"$#,##0.00\"
               Range(\"A5\").Value = 7
               Range(\"A6\").Value = 3.5: Range(\"A6\").NumberFormat = \"0.000\"
               Range(\"A13\").Value = 0.5: Range(\"A13\").NumberFormat = \"[h]:mm\"
               Dim f As Variant, i As Long, out As String
               f = Array(\"=A1+30\", \"=A1*2\", \"=A2-A1\", \"=A5+A1\", \"=A3+A1\", \"=A5*1+A1\", \"=A1+(A5*1)\", _
                         \"=SUM(A5,A3)\", \"=SUM(A1,A2)\", \"=SUM(A5:A6)\", \"=ROUND(A4,0)\", \"=ABS(A1)+A1\", _
                         \"=IFERROR(A1+1,0)\", \"=TODAY()\", \"=NOW()\", \"=TIME(1,2,3)\", \"=PMT(0.1,10,1000)\", \"=A13+A13\", \"=-A1\")
               For i = 0 To UBound(f)
                 Cells(i + 1, 3).Formula = f(i)
                 out = out & Cells(i + 1, 3).NumberFormat & \"~\"
               Next i
               Range(\"E1:E3\").Formula = \"=A1+1\"
               Range(\"F2\").NumberFormat = \"0.0\"
               Range(\"F1:F3\").Formula = \"=A1+1\"
               Range(\"G1:G3\").Formula = \"=A5+1\"
               Range(\"H1:H3\").Formula = Application.Transpose(Array(\"=A5+1\", \"=A1+1\", \"=A3+1\"))
               Ask = out & Range(\"E3\").NumberFormat & \"|\" & Range(\"F2\").NumberFormat & \"|\" & _
                     Range(\"G2\").NumberFormat & \"|\" & Range(\"H1\").NumberFormat & \",\" & _
                     Range(\"H2\").NumberFormat & \",\" & Range(\"H3\").NumberFormat & \"|\" & TypeName(Range(\"A13\").Value)
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String(
                "m/d/yyyy~General~General~m/d/yyyy~0%~General~General~0%~General~General~\
                 $#,##0.00~m/d/yyyy~General~m/d/yyyy~m/d/yyyy h:mm~h:mm AM/PM~\
                 $#,##0.00_);[Red]($#,##0.00)~[h]:mm~m/d/yyyy~\
                 m/d/yyyy|0.0|General|General,m/d/yyyy,0%|Double"
                    .to_string()
            )
        );
    }

