    /// SUBTOTAL under a filter counts only what is showing, and the sheet's
    /// AutoFilter object names its block. Every answer here is Excel's.
    #[test]
    fn subtotal_under_a_filter_adds_what_is_showing() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim i As Long
               Range(\"A1:C1\").Value = Array(\"name\", \"dept\", \"amount\")
               For i = 2 To 11
                 Cells(i, 1).Value = \"P\" & i
                 Cells(i, 2).Value = Choose((i Mod 3) + 1, \"a\", \"b\", \"c\")
                 Cells(i, 3).Value = i * 1000
               Next i
               Range(\"A1:C11\").AutoFilter Field:=2, Criteria1:=\"a\"
               Range(\"E1\").Formula = \"=SUBTOTAL(9,C2:C11)\"
               Ask = WorksheetFunction.Subtotal(9, Range(\"C2:C11\")) & \"|\" & _
                     WorksheetFunction.Sum(Range(\"C2:C11\")) & \"|\" & _
                     ActiveSheet.AutoFilter.Range.Address & \"|\" & TypeName(ActiveSheet.AutoFilter)
               ActiveSheet.AutoFilterMode = False
               Ask = Ask & \"|\" & (ActiveSheet.AutoFilter Is Nothing)
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String("18000|65000|$A$1:$C$11|AutoFilter|True".to_string())
        );
    }

    /// An apostrophe marks a cell as text, and the mark comes and goes as
    /// Excel's does. Every answer here is Excel's.
    #[test]
    fn an_apostrophe_marks_a_cell_as_text() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Function Ask() As String
               Dim out As String
               Range(\"A1\").Value = \"'0123\"
               out = Range(\"A1\").Value & \"|\" & Range(\"A1\").PrefixCharacter & \"|\" & Range(\"A1\").Formula
               Range(\"A1\").Value = \"text\"
               out = out & \"|\" & Range(\"A1\").PrefixCharacter
               Range(\"A1\").Value = \"46\"
               out = out & \"|\" & TypeName(Range(\"A1\").Value) & Range(\"A1\").PrefixCharacter
               Range(\"A2\").Value = \"'45\"
               Range(\"A2\").Copy Range(\"B2\")
               out = out & \"|\" & Range(\"B2\").PrefixCharacter & TypeName(Range(\"B2\").Value)
               Range(\"A2\").ClearContents
               out = out & \"|\" & Range(\"A2\").PrefixCharacter
               Range(\"A3:A4\").Value = \"'7\"
               out = out & \"|\" & Range(\"A3:A4\").PrefixCharacter & \"|\" & IsNull(Range(\"A1:A3\").PrefixCharacter)
               Range(\"A5\").NumberFormat = \"@\"
               Range(\"A5\").Value = \"12\"
               Ask = out & \"|\" & TypeName(Range(\"A5\").Value) & Range(\"A5\").PrefixCharacter
             End Function
",
        )
        .unwrap();
        let answer = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Ask", vec![], &mut host).unwrap()
        };
        assert_eq!(
            answer,
            Value::String("0123|'|0123|'|Double|'String||'|True|String".to_string())
        );
    }

    /// Brackets after a property that takes none index its answer, and a
    /// range's two-index item counts back from its corner. Every answer here
